// Üretilen dosya: tool/ozgun/uret.py. Bilişim ve Algoritmalar · Sıralama ve arama algoritmaları uygulamalı (orta).
const ozComputing7Orta = <(String, String, List<String>, String)>[
  ('Kendi kendini düzenleyen bir liste \'başa taşı\' (move-to-front) kuralını kullanıyor: erişilen öğe listenin başına alınıyor. Liste A, B, C, D, E iken sırasıyla D, B, D öğelerine erişilirse liste hangi duruma gelir?', 'D, B, A, C, E', ['B, D, A, C, E', 'D, A, B, C, E', 'A, B, C, D, E'], 'D başa alınınca D, A, B, C, E; B başa alınınca B, D, A, C, E; yeniden D başa alınınca D, B, A, C, E olur.'),
  ('\'Yer değiştir\' (transpose) kuralıyla düzenlenen bir listede erişilen öğe yalnız bir önündeki öğeyle yer değiştirir. Liste A, B, C, D iken D\'ye art arda iki kez erişilirse liste nasıl olur?', 'A, D, B, C', ['D, A, B, C', 'A, B, D, C', 'A, B, C, D'], 'İlk erişimde D, C ile yer değiştirir (A, B, D, C); ikinci erişimde B ile yer değiştirir ve A, D, B, C elde edilir.'),
  ('Bir listede A, B ve C öğeleri sırasıyla 0,5, 0,3 ve 0,2 olasılıkla aranıyor ve her arama başarılı oluyor. Öğeler beklenen karşılaştırma sayısını en aza indirecek biçimde dizilirse doğrusal arama ortalama kaç karşılaştırma yapar?', '1,7', ['2,0', '1,25', '2,3'], 'En olası öğe başa konur: 1·0,5 + 2·0,3 + 3·0,2 = 0,5 + 0,6 + 0,6 = 1,7.'),
  ('0\'dan başlayan indislerle 1, 3, 3, 3, 5, 8 dizisinde \'alt sınır\' (değerden küçük olmayan ilk elemanın indisi) işlemi 4 için hangi indisi verir?', '4', ['3', '5', '−1'], '4\'ten küçük olmayan ilk eleman 5\'tir ve 4 numaralı indistedir. Değer dizide olmasa da alt sınır, onun sırayı bozmadan ekleneceği yeri gösterir.'),
  ('Sıralı 2, 4, 4, 4, 4, 7, 9 dizisinde 4 değerinin kaç kez geçtiği iki ikili aramayla bulunuyor: değerden kesin büyük ilk elemanın indisinden, değerden küçük olmayan ilk elemanın indisi çıkarılıyor. Sonuç kaçtır?', '4', ['3', '5', '−1'], '0\'dan sayılınca 4\'ten küçük olmayan ilk indis 1, 4\'ten büyük ilk indis 5\'tir; 5 − 1 = 4.'),
  ('Sıralı bir dizide [a, b] kapalı aralığına düşen eleman sayısını O(log n) sürede bulmak isteyen bir algoritma ne yapar?', 'b\'den büyük ilk indisten a\'dan küçük olmayan ilk indisi çıkarır', ['Elemanları tek tek a ve b ile karşılaştırır', 'a ve b\'nin indislerini toplayıp sonucu ikiye bölerek orta noktayı bulur', 'Diziyi a ve b\'ye göre yeniden sıralar'], 'İki ikili arama aralığın iki ucunu bulur; aradaki indislerin sayısı aralıktaki eleman sayısıdır. Örneğin 1, 4, 6, 9, 12, 15, 20\'de [5, 13] için 6, 9, 12 bulunur.'),
  ('Python\'daki bisect_left ile bisect_right işlevleri hangi durumda farklı sonuç verir?', 'Aranan değer dizide en az bir kez bulunduğunda', ['Dizi boş olduğunda', 'Aranan değer bütün elemanlardan büyük olduğunda', 'Dizi tek elemanlı olduğunda'], 'Değer dizide yoksa iki işlev de aynı ekleme yerini verir; değer varsa biri eşitlerin soluna, öteki sağına işaret eder.'),
  ('Beş elemanın hepsi 2 olan 2, 2, 2, 2, 2 dizisinde orta indisi ⌊(alt + üst)/2⌋ ile seçen ve ilk eşleşmede duran standart ikili arama, 2 değerini aradığında kaçıncı elemanı döndürür?', '3. elemanı', ['1. elemanı', '5. elemanı', '2. elemanı'], '0–4 aralığında ilk orta indis 2\'dir; bu eleman eşleştiği için arama hemen durur ve 3. eleman döner. Standart ikili arama eşitler arasında hangisini bulacağını garanti etmez.'),
  ('Kapalı [alt, üst] aralığıyla çalışan bir ikili aramada döngü koşulu \'alt ≤ üst\' yerine yanlışlıkla \'alt < üst\' yazılmıştır. Bu hata hangi durumda yanlış sonuç doğurur?', 'Aralık tek elemana inince o eleman denetlenmeden döngüden çıkılır', ['Dizi çift sayıda eleman içerdiğinde sonsuz döngüye girilir', 'Aranan değer ilk ortadaki elemansa bulunamaz', 'Dizi sıralıysa bile her arama başarısız olur'], 'alt = üst olduğunda aralıkta hâlâ bir eleman vardır; \'alt < üst\' koşulu bu son elemana bakmadan aramayı bitirir ve değer oradaysa \'yok\' denir.'),
  ('Yarı açık [alt, üst) aralığıyla yazılan ikili aramada n elemanlı bir dizi için başlangıç değerleri ve \'orta elemandan küçük\' durumundaki güncelleme hangisidir?', 'alt = 0, üst = n; üst ← orta', ['alt = 0, üst = n − 1; üst ← orta − 1', 'alt = 1, üst = n; üst ← orta + 1', 'alt = 0, üst = n; üst ← orta − 1'], 'Yarı açık aralıkta üst sınır aralığa dahil değildir; bu yüzden n ile başlar ve orta eleman elendiğinde üst doğrudan orta yapılır.'),
  ('50, 40, 30, 20, 10 biçiminde azalan sıralı bir diziye, artan sıra varsayan standart ikili arama 40 değeri için uygulanıyor. Sonuç ne olur?', 'Değer dizide olduğu hâlde bulunamaz', ['40 ilk karşılaştırmada bulunur', '40 ikinci karşılaştırmada, sol yarıya geçildikten sonra bulunur', 'Algoritma sonsuz döngüye girer'], 'Orta eleman 30\'dur; 40 > 30 olduğundan algoritma sağa gider, oysa 40 soldadır. Sağda 20 ve 10\'a bakıp \'yok\' der.'),
  ('Sıralı bir dizinin elemanlarının sağa doğru döndürülmesiyle elde edilen 15, 18, 2, 3, 6, 12 dizisinde en küçük eleman ikili aramayla bulunabilir. Bu dizi özgün sıralı diziden sağa doğru kaç konum döndürülmüştür?', '2', ['3', '5', '10'], 'Özgün dizi 2, 3, 6, 12, 15, 18\'dir. Sağa döndürme sayısı en küçük elemanın 0\'dan sayılan indisine eşittir; 2 değeri 2 numaralı indistedir.'),
  ('Döndürülmüş sıralı bir dizide (ör. 4, 5, 6, 7, 0, 1, 2) ikili aramanın yine logaritmik sürede çalışabilmesini sağlayan özellik hangisidir?', 'Ortadan bölününce iki yarıdan en az biri kendi içinde sıralıdır', ['Döndürülmüş dizinin ilk elemanı her zaman dizinin en küçük elemanıdır', 'Dizinin ortasındaki eleman her zaman en büyüktür', 'Döndürülmüş dizide yinelenen değer bulunamaz'], 'Kırılma noktası yalnız bir yarıda olabilir; sıralı yarının uçlarına bakılarak hedefin o yarıda olup olmadığı anlaşılır ve öteki yarı elenir.'),
  ('Ağırlıkları sırasıyla 3, 2, 2, 4, 1, 4 olan paketler bu sırayla, her gün art arda gelen paketler bir kamyona yüklenerek 3 günde taşınacak. Kamyonun kapasitesi ikili aramayla belirleniyor. Gereken en küçük kapasite kaçtır?', '6', ['5', '7', '16'], 'Kapasite 5 ise yükler [3, 2], [2], [4, 1], [4] olur ve 4 gün gerekir. Kapasite 6 ile [3, 2], [2, 4], [1, 4] üç güne sığar.'),
  ('Paket taşıma probleminde (sıra korunarak günlere bölme) kapasite için ikili aramanın başlangıç aralığı en doğal olarak nasıl seçilir?', 'En ağır paketten bütün ağırlıkların toplamına kadar', ['1\'den en ağır pakete kadar', 'Ortalama paket ağırlığından en ağır paketin ağırlığına kadar', '0\'dan paket sayısına kadar'], 'En ağır paket taşınabilmeli, bu yüzden kapasite ondan küçük olamaz; toplam ağırlık ise her şeyi tek günde taşır, daha büyüğüne gerek yoktur.'),
  ('Sıralı 2, 9, 15, 22 dizisinde 13\'e en yakın eleman aranıyor. Alt sınır araması 13\'ten küçük olmayan ilk eleman olarak 15\'i bulduktan sonra algoritmanın yapması gereken nedir?', 'Bulunan elemanı bir öncekiyle karşılaştırıp farkı küçük olanı seçmek', ['Hiçbir karşılaştırma yapmadan 15 değerini döndürmek', 'Dizinin son elemanını da aday olarak eklemek', 'Aramayı sağ yarıda baştan başlatıp 13\'ten büyük bütün elemanları denetlemek'], 'En yakın değer ya alt sınırdaki eleman ya da ondan hemen önceki elemandır. 13 için |15 − 13| = 2 ve |9 − 13| = 4 olduğundan 15 seçilir; başka değer için 9 da çıkabilirdi.'),
  ('Özyinelemeli yazılmış bir ikili arama 1 milyon elemanlı bir dizide çalışıyor. Çağrı yığınının derinliği en fazla yaklaşık ne kadar olur?', '20 çağrı', ['1000 çağrı', '500 000 çağrı', '2 çağrı'], 'Her çağrıda aralık yarıya iner; 2²⁰ ≈ 1 milyon olduğundan iç içe çağrı sayısı yaklaşık 20\'de kalır.'),
  ('Bir dizide ikili aramayla sözcük aranırken karşılaştırma büyük-küçük harfe duyarlı yapılıyor, ama dizi harf duyarsız sıralanmış. Hangi sorun beklenir?', 'Bazı sözcükler dizide olduğu hâlde bulunamayabilir', ['Arama her zaman ilk elemanı döndürür', 'Dizi kendiliğinden yeniden sıralanır', 'Arama süresi doğrusala çıkar ama bulunan sonuç her zaman doğru olur'], 'Sıralama ile aramanın aynı karşılaştırma kuralını kullanması gerekir. Kurallar farklıysa orta eleman yanlış yönü gösterebilir ve var olan sözcük kaçırılır.'),
  ('Önce artıp sonra azalan 1, 3, 8, 12, 4, 2 dizisinde en büyük eleman ikili aramayla aranıyor: a[orta] < a[orta + 1] ise alt ← orta + 1, değilse üst ← orta yapılıyor (orta = ⌊(alt + üst)/2⌋). Ortada sırasıyla hangi elemanlara bakılır?', '8, 4, 12', ['8, 12', '3, 8, 12, 4, 2', '8, 12, 4'], '0–5\'te orta 8\'dir ve 8 < 12 olduğundan alt = 3. 3–5\'te orta 4\'tür, 4 > 2 olduğundan üst = 4. 3–4\'te orta 12\'dir, 12 > 4 olduğundan üst = 3 ve arama 12\'de biter.'),
  ('Dizinin iki ucunun dışındaki değerler eksi sonsuz kabul edilirse, boş olmayan her dizide en az bir tepe (komşularından küçük olmayan eleman) bulunur. Bunun gerekçesi hangisidir?', 'Dizinin en büyük elemanı her zaman bir tepedir', ['Dizinin ilk elemanı her zaman bir tepedir', 'Sıralı dizilerde tepe her zaman tam ortadaki elemandır', 'Her dizide en az iki eşit eleman vardır'], 'En büyük eleman hiçbir komşusundan küçük olamaz; dolayısıyla tepe tanımını sağlar. İkili arama ise en büyük elemanı değil, herhangi bir tepeyi daha hızlı bulur.'),
  ('Önce artan sonra azalan (bitonik) bir dizide belirli bir değeri O(log n) sürede bulmak için izlenebilecek yol hangisidir?', 'Tepeyi bulup artan yarıda artan, azalan yarıda azalan ikili arama yapmak', ['Diziyi tamamen sıralayıp tek bir ikili arama yapmak', 'Diziyi baştan sona iki kez doğrusal olarak tarayıp eşleşmeleri saymak', 'Yalnız artan yarıda ikili arama yapmak'], 'Tepe dizinin iki sıralı parçasını ayırır. Tepe ikili aramayla bulunur, ardından her parçada o parçanın sırasına uygun ikili arama yapılır; toplam üç logaritmik arama gerekir.'),
  ('f(x) = −(x − 7)² fonksiyonunun en büyük noktası [0, 12] aralığında üçlü aramayla aranıyor. İç noktalar 4 ve 8 seçiliyor ve f(4) < f(8) bulunuyor. Bir sonraki adımda hangi kısım elenir?', '4\'ten küçük x değerleri', ['8\'den büyük x değerleri', '4 ile 8 arasındaki değerler', '8\'den küçük bütün değerler'], 'Tek tepeli fonksiyonda f(4) < f(8) ise tepe 4\'ün solunda olamaz; çünkü tepe orada olsaydı fonksiyon 4\'ten 8\'e azalırdı. Bu yüzden [0, 4) atılır.'),
  ('Uzunluğu 81 olan bir aralıkta üçlü arama yapılıyor ve her adımda aralığın üçte biri atılıyor. İki adımdan sonra aralığın uzunluğu kaç olur?', '36', ['27', '9', '54'], 'Her adımda uzunluk 2/3 ile çarpılır: 81 · 2/3 = 54, 54 · 2/3 = 36.'),
  ('Sıralı bir dizide bir değeri aramak için üçlü arama neden ikili aramadan daha iyi değildir?', 'Adım başına iki karşılaştırma yaptığından toplam karşılaştırma sayısı artar', ['Üçlü arama sıralı dizilerde yalnız tek sayıda eleman varsa doğru çalışır', 'Üçlü arama her zaman doğrusal zaman alır', 'Üçlü arama sıralı olmayan dizilerde bile doğru çalıştığı için gereksiz iş yapar'], 'Üçlü arama adım sayısını log₃ n\'ye indirir ama her adımda iki karşılaştırma yapar: 2·log₃ n ≈ 1,26·log₂ n. Bu, ikili aramanın log₂ n karşılaştırmasından fazladır.'),
  ('10, 20, 30, …, 100 biçiminde düzgün aralıklı 10 elemanlı dizide (indisler 0–9) 70 değeri interpolasyon aramasıyla aranıyor. Tahmin formülü konum = alt + (x − a[alt]) · (üst − alt) / (a[üst] − a[alt]) ise ilk tahmin edilen indis kaçtır?', '6', ['4', '5', '10'], 'konum = 0 + (70 − 10) · 9 / (100 − 10) = 60 · 9 / 90 = 6. a[6] = 70 olduğundan değer tek denemede bulunur.'),
  ('1, 2, 4, 8, 16, …, 2²⁰ gibi değerleri üstel artan sıralı bir dizide interpolasyon araması küçük bir değer için neden kötü çalışır?', 'Doğrusal oranlama tahmini hep hedefin çok uzağına düşer ve aralık ancak yavaşça daralır', ['Dizi sıralı olmadığı için arama başarısız olur', 'Formül negatif indis üretir ve program çöker', 'Değerler tam sayı olduğundan formül uygulanamaz'], 'Büyük uç değer formülü baskıladığından tahminler hep dizinin başına düşer; aralık her adımda yalnız bir iki eleman küçülebilir ve süre doğrusala yaklaşır.'),
  ('İnterpolasyon araması uygulanırken a[alt] = a[üst] durumunun ayrıca ele alınması neden gerekir?', 'Formüldeki payda sıfır olur', ['Dizi bu durumda sırasız sayılır', 'Aranan değer kesinlikle dizide yoktur', 'Arama alanı iki katına çıkar'], 'Tahmin formülünde (a[üst] − a[alt]) ile bölünür; aralıktaki değerler eşitse sıfıra bölme oluşur. Bu durumda yalnız a[alt] = x olup olmadığına bakılır.'),
  ('Üstel arama (exponential search) sıralı bir dizide önce 1, 2, 4, 8, … indislerini denetleyerek aranan değeri geçen ilk indisi bulur. Elemanları a[i] = 3i olan 100 elemanlı dizide 75 aranırsa sonraki ikili arama hangi indis aralığında yapılır?', '16 ile 32 arası', ['8 ile 16 arası', '32 ile 64 arası', '0 ile 64 arası'], 'a[16] = 48 < 75 ve a[32] = 96 ≥ 75 olduğundan değer 16 ile 32 arasındadır; ikili arama bu aralıkta yapılır ve 25. indis bulunur.'),
  ('Satırları ve sütunları artan sıralı 4 × 4 matrisin satırları şöyledir: [1, 4, 7, 11], [2, 5, 8, 12], [3, 6, 9, 16], [10, 13, 14, 17]. Sağ üst köşeden başlayan merdiven aramasıyla 6 bulunurken (6 dahil) kaç elemana bakılır?', '5', ['4', '6', '11'], 'Bakılan elemanlar 11, 7, 4, 5, 6\'dır: 11 ve 7 büyük olduğu için sola, 4 ve 5 küçük olduğu için aşağı gidilir.'),
  ('Satır ve sütunları sıralı bir matriste merdiven aramasına sol üst köşeden başlanamamasının nedeni nedir?', 'Hem sağa hem aşağı gidince değerler arttığından hangi yöne gidileceği belirlenemez', ['Sol üst köşedeki eleman hiçbir zaman aranmaz', 'Sol üst köşeden başlamak her zaman sonsuz döngü yaratır', 'Matrisin ilk satırı sıralı olmak zorunda değildir'], 'Sol üst eleman hedeften küçükse hem sağdaki hem aşağıdaki hücreler daha büyük olabilir; tek bir satır ya da sütunu elemeye yetecek bilgi yoktur.'),
  ('3 satır ve 4 sütunlu bir matriste satır sonu bir sonraki satır başından küçük olacak şekilde tüm elemanlar sıralıdır; bu yüzden matris 12 elemanlı tek bir dizi gibi ikili aramayla taranabilir. 0\'dan sayılan 7 numaralı sanal indis hangi hücreye karşılık gelir?', '1. satır, 3. sütun', ['2. satır, 1. sütun', '1. satır, 2. sütun', '0. satır, 7. sütun'], 'Satır = 7 div 4 = 1, sütun = 7 mod 4 = 3 (ikisi de 0\'dan sayılır).'),
  ('Sıçramalı (jump) arama sıralı veride hep ileri doğru atlar ve yalnız son blokta bir kez geri döner. Bu özellik onu hangi ortamda ikili aramaya göre avantajlı kılar?', 'Geriye doğru gitmenin pahalı olduğu ortamlarda', ['Verinin sırasız olduğu ortamlarda', 'Verinin tamamen bellekte bulunduğu ve rastgele erişimin ucuz olduğu ortamlarda', 'Aranan değerin her zaman dizinin sonunda olduğu durumlarda'], 'İkili arama ileri geri büyük sıçramalar yapar. Sıçramalı arama ise ileri yönde blok blok ilerleyip yalnız bir kez geri döner; geri sarmanın yavaş olduğu ortamlarda bu önemlidir.'),
  ('Sıralı bir dizide toplamı hedefe eşit çift arayan iki işaretçi yönteminde toplam hedeften küçükse sol işaretçiyi sağa kaydırmak neden güvenlidir?', 'Sol eleman en büyük kalan elemanla bile hedefe ulaşamıyorsa başka bir çiftte de işe yaramaz', ['Sol işaretçinin gösterdiği eleman her zaman dizinin en büyüğüdür', 'Sağ işaretçi o noktadan sonra hiçbir zaman hareket etmeyeceği için sola kaydırmak gereksizdir', 'Toplam küçükse dizide çözüm bulunmadığı kesinleşmiştir'], 'Sağ işaretçi aday kalan en büyük değeri gösterir. Sol eleman onunla bile yetmiyorsa daha küçük ortaklarla da yetmez ve güvenle elenebilir.'),
  ('n elemanlı bir dizide toplamı sıfır olan üçlüleri bulmak için dizi önce sıralanıyor, sonra her eleman için kalan kısımda iki işaretçi taraması yapılıyor. Bu yöntemin toplam süresi hangi mertebededir?', 'n²', ['n log n', 'n³', 'n'], 'Sıralama n log n sürer; ardından her n eleman için doğrusal bir iki işaretçi taraması yapılır. Baskın terim n · n = n²\'dir; üç iç içe döngüyle kaba kuvvet n³ olurdu.'),
  ('Sıralı bir dizide farkı tam olarak k olan bir çift aranırken iki işaretçi nasıl kullanılır?', 'İkisi de baştan başlar; fark küçükse öndeki, büyükse arkadaki işaretçi ilerletilir', ['Biri baştan biri sondan başlar ve birbirine doğru yürür', 'İkisi de sondan başlar ve her adımda ikisi birden bir konum geri gider', 'Bir işaretçi sabit kalır, öteki rastgele konumlara atlar'], 'Farkta artırmak için öndeki (büyük) eleman ileri, azaltmak için arkadaki (küçük) eleman ileri alınır; iki işaretçi de aynı yönde gider ve tarama doğrusal kalır.'),
  ('Sıralı listelerden biri 10, öteki 1 milyon elemanlıysa ortak elemanları bulmanın en hızlı yolu hangisidir?', 'Küçük listedeki her eleman için büyük listede ikili arama yapmak', ['İki listeyi baştan sona yan yana yürüyerek taramak', 'Büyük listedeki her eleman için küçük listeyi baştan sona doğrusal olarak taramak', 'İki listeyi birleştirip yeniden sıralamak'], 'Yan yana yürüme yaklaşık 1 milyon adım sürer. Küçük listedeki 10 eleman için yapılan 10 ikili arama ise yaklaşık 10 · 20 = 200 karşılaştırma gerektirir.'),
  ('Sıralı 1, 3, 8 ve 2, 4, 9, 10 dizilerinin tümünün ortancası, birleştirme mantığıyla küçükten büyüğe yürüyerek bulunuyor. Ortanca kaçtır?', '4', ['3', '8', '3,5'], 'Toplam 7 eleman vardır; birleştirilmiş sıra 1, 2, 3, 4, 8, 9, 10 olduğundan dördüncü eleman olan 4 ortancadır. Yürüyüş dördüncü elemanda durdurulabilir.'),
  ('Bir dizide birbirine en yakın iki sayıyı (farkı en küçük olan çifti) bulmak için önce sıralama yapılırsa, sonrasında hangi karşılaştırmalar yeterlidir?', 'Yalnız komşu elemanların farkları', ['Her elemanın listenin ilk elemanıyla olan farkı', 'Bütün olası çiftlerin farkları', 'Yalnız ilk ve son elemanın farkı'], 'Sıralı dizide en yakın çift mutlaka yan yanadır; çünkü aralarına giren başka bir eleman ikisinden birine daha yakın olurdu. n − 1 fark yeterlidir.'),
  ('Bir dizide hiç tekrar eden değer olup olmadığını denetlemek için \'önce sırala, sonra tara\' yaklaşımı ile \'her çifti karşılaştır\' yaklaşımı karşılaştırıldığında 1 milyon eleman için hangisi doğrudur?', 'Sıralayıp komşulara bakmak çok daha az işlem gerektirir', ['Her çifti karşılaştırmak her zaman daha hızlıdır', 'İki yaklaşım aynı sayıda karşılaştırma yapar', 'Sıralama tekrar eden değerleri sildiği için kullanılamaz'], 'Her çift yaklaşımı n(n − 1)/2 ≈ 5·10¹¹ karşılaştırma ister; sıralama yaklaşık n log n ≈ 2·10⁷ işlem, ardından n − 1 komşu karşılaştırması yeter.'),
  ('Sıralı bir dizide hedef toplama en yakın çifti iki işaretçiyle arayan algoritmanın her adımda yapması gereken ek iş nedir?', 'O anki toplamın hedefe uzaklığını en iyi değerle karşılaştırıp gerekirse güncellemek', ['Diziyi her adımda yeniden sıralamak', 'İşaretçileri her adımda başa döndürmek', 'Bulunan ilk çiftte hemen durmak'], 'Tam eşitlik aranmadığı için yöntem sonuna kadar sürer; her adımda |toplam − hedef| hesaplanıp şimdiye kadarki en küçük değerle karşılaştırılır.'),
  ('Kabarcık sıralaması 2, 3, 4, 5, 1 listesine uygulanıyor. Sondaki küçük 1 değeri her geçişte yalnız bir konum sola ilerleyebildiğine göre, listenin sıralı hâle gelmesi için kaç geçiş gerekir?', '4', ['1', '2', '5 ya da daha fazla'], 'Büyük değerler bir geçişte sona kadar \'kabarır\', ama sondaki küçük değer (kaplumbağa) her geçişte bir adım sola gelir. 1\'in başa ulaşması dört geçiş sürer.'),
  ('Kokteyl (çift yönlü kabarcık) sıralaması 2, 3, 4, 5, 1 listesine uygulanıyor: önce soldan sağa, sonra sağdan sola bir geçiş yapılıyor. Bu iki geçişten sonra liste nasıldır?', '1, 2, 3, 4, 5', ['2, 3, 4, 1, 5', '1, 2, 3, 5, 4', '2, 1, 3, 4, 5'], 'İleri geçişte yalnız 5 ile 1 yer değiştirir: 2, 3, 4, 1, 5. Geri geçişte 1 art arda takaslarla başa taşınır ve liste sıralanır.'),
  ('Kabarcık sıralamasında takas koşulu \'a[j] > a[j + 1]\' yerine \'a[j] ≥ a[j + 1]\' yazılırsa algoritmanın hangi özelliği bozulur?', 'Kararlılığı; eşit elemanların göreli sırası değişir', ['Doğruluğu; liste artık sıralı çıkmaz', 'Yerindeliği; sıralama için ek bir dizi gerekli hâle gelir', 'Sonlanması; döngü hiç bitmez'], 'Eşit komşular da takas edilince aynı değerli kayıtların başlangıçtaki sırası tersine dönebilir. Sıralama yine doğru olur, ama kararlı olmaz.'),
  ('Kabarcık sıralamasının bir iyileştirmesinde her geçişte son takasın yapıldığı konum kaydediliyor. Bu bilgi sonraki geçişte nasıl kullanılır?', 'Sonraki geçiş yalnız o konuma kadar yürütülür', ['Sonraki geçiş o konumdan başlatılır', 'O konumdaki eleman listeden çıkarılır', 'Sonraki geçişte o konum iki kez karşılaştırılır'], 'Son takastan sonraki kısımda hiç takas olmadığından o bölüm zaten sıralı ve yerleşmiştir; bir sonraki geçişin oraya girmesine gerek yoktur.'),
  ('Tek-çift transpozisyon sıralaması sırayla iki tür evre uygular: \'tek\' evrede (1., 2.), (3., 4.), … elemanlar; \'çift\' evrede (2., 3.), (4., 5.), … elemanlar karşılaştırılıp gerekirse takas edilir. 4, 3, 2, 1 listesine önce tek, sonra çift evre uygulanınca liste nasıl olur?', '3, 1, 4, 2', ['3, 4, 1, 2', '4, 3, 1, 2', '1, 2, 3, 4'], 'Tek evrede (4, 3) ve (2, 1) takas edilir: 3, 4, 1, 2. Çift evrede (4, 1) takas edilir: 3, 1, 4, 2.'),
  ('Tek-çift transpozisyon sıralamasının paralel işlemcilerde verimli çalışabilmesinin nedeni nedir?', 'Bir evredeki karşılaştırmalar birbirinden bağımsızdır ve aynı anda yapılabilir', ['Her evrede yalnız tek bir karşılaştırma yapılır', 'Algoritma hiç takas yapmadan sıralar', 'Evre sayısı eleman sayısından bağımsızdır'], 'Bir evrede karşılaştırılan çiftler ortak eleman paylaşmaz; her çifti ayrı bir işlemci aynı anda işleyebilir. n evre sonunda liste sıralanmış olur.'),
  ('n elemanlı bir liste tek-çift transpozisyon sıralamasıyla sıralanıyor. Girdi ne olursa olsun listenin sıralı olmasını garanti eden evre sayısı kaçtır?', 'n', ['log₂ n', 'n²', '2'], 'Tek ve çift evrelerin art arda n kez uygulanmasının her girdiyi sıraladığı kanıtlanmıştır; en kötü durumda bir eleman listenin bir ucundan öbür ucuna bu kadar evrede ulaşır.'),
  ('Cüce sıralamasının yaptığı takas sayısı aynı listede hangi algoritmanın yaptığı kaydırma sayısıyla aynıdır?', 'Eklemeli sıralama', ['Birleştirmeli sıralama', 'Yığın sıralaması', 'Sayma sıralaması'], 'Cüce sıralaması bir elemanı geri geri takas ederek doğru yerine götürür; bu, eklemeli sıralamanın elemanı kaydırarak yerleştirmesiyle aynı adımlara denk gelir. İkisi de ters çift sayısı kadar yer değiştirme yapar.'),
  ('Tarak (comb) sıralaması 10 elemanlı bir listede boşluğu 10\'dan başlatıp her turda 1,3\'e bölerek ve aşağı yuvarlayarak küçültüyor. Kullanılan boşluk dizisi hangisidir?', '7, 5, 3, 2, 1', ['5, 2, 1', '9, 8, 7, 6, 5, 4, 3, 2, 1', '8, 4, 2, 1'], '10/1,3 ≈ 7,69 → 7; 7/1,3 ≈ 5,38 → 5; 5/1,3 ≈ 3,85 → 3; 3/1,3 ≈ 2,31 → 2; 2/1,3 ≈ 1,54 → 1.'),
  ('Tarak sıralaması ile Shell sıralaması ikisi de azalan boşluklarla çalışır. Aralarındaki temel fark hangisidir?', 'Tarak, boşluklu kabarcık geçişleri; Shell ise boşluklu eklemeli sıralama yapar', ['Tarak ek bir dizi kullanır, Shell yerinde çalışan bir algoritmadır', 'Tarak yalnız sayıları, Shell yalnız metinleri sıralayabilir', 'Tarakta boşluk her turda artar, Shell\'de ise hep sabit kalır'], 'İkisi de uzak elemanları önce yaklaştırır. Tarak her boşlukta tek bir kabarcık geçişi yapar; Shell her boşlukta alt dizileri eklemeli sıralamayla tamamen sıralar.'),
  ('Her geçişte kalanların hem en küçüğünü başa hem en büyüğünü sona yerleştiren çift yönlü seçmeli sıralama, 8 elemanlı bir listeyi en fazla kaç geçişte sıralar?', '4', ['7', '8', '3'], 'Her geçiş iki elemanı kesin yerine koyar; 8 eleman için 8/2 = 4 geçiş yeter.'),
  ('Yazma işleminin çok pahalı olduğu ve okumanın ucuz olduğu bir bellekte (ör. yıpranan flaş bellek) basit algoritmalar arasında seçmeli sıralamanın tercih edilme nedeni nedir?', 'En fazla n − 1 takasla yetinerek yazma sayısını düşük tutması', ['Karşılaştırma sayısının girdinin düzeninden bağımsız olarak her durumda n log n olması', 'Eşit elemanların sırasını her durumda koruması', 'Sıralı girdide hiç karşılaştırma yapmadan bitmesi'], 'Kabarcık ve eklemeli sıralama en kötü durumda karesel sayıda yer değiştirme yapar; seçmeli sıralama ise her konuma en fazla bir takas yapar.'),
  ('Etiketleri 2a, 2b ve 1 olan (2a ile 2b\'nin anahtarı eşit) üç kayda standart seçmeli sıralama uygulanıyor. İlk adımda en küçük olan 1 baştaki elemanla takas edilince sıra ne olur?', '1, 2b, 2a', ['1, 2a, 2b', '2a, 2b, 1', '2b, 1, 2a'], '1 ile 2a takas edilir; 2a sona gider ve sıra 1, 2b, 2a olur. Eşit anahtarlı 2a ile 2b\'nin sırası değiştiği için algoritma kararsızdır.'),
  ('Seçmeli sıralamayı kararlı hâle getirmek için takas yerine ne yapılabilir?', 'En küçük eleman çıkarılıp aradaki elemanlar bir sağa kaydırılarak başa eklenir', ['Takaslar eleman yerine indislerle yapılır', 'Her adımda kalanların en küçüğü yerine en büyüğü seçilip listenin sonuna takas edilir', 'Liste önce ters çevrilir, sonra takas yapılır'], 'Uzak takas, aradaki eşit elemanların önünden atlayıp sırayı bozar. Kaydırarak yerleştirme sırayı korur, ama yazma sayısını artırır.'),
  ('İkili eklemeli sıralama, yeni elemanın sıralı bölümdeki yerini ikili aramayla bulur. Bu değişiklik aşağıdakilerden hangisini azaltır?', 'Karşılaştırma sayısını; kaydırma sayısı yine karesel kalır', ['Kaydırma sayısını; karşılaştırma sayısı ise artar', 'Hem karşılaştırma hem de kaydırma sayısını n log n\'e indirir', 'Yalnız ek bellek kullanımını, başka hiçbir şeyi değiştirmez'], 'Yer O(log i) karşılaştırmayla bulunur; ancak elemanı oraya koymak için aradaki elemanların yine tek tek kaydırılması gerekir.'),
  ('Eklemeli sıralama 1, 2, 3, 5, 4, 6 listesine uygulanıyor; her eleman, kendisinden büyük olmayan bir elemana rastlayana kadar soldakilerle karşılaştırılıyor. Toplam kaç karşılaştırma yapılır?', '6', ['5', '4', '15'], 'Yerinde olan her eleman tek karşılaştırma yapar (5 adım). Yalnız 4, önce 5 ile (kaydırma) sonra 3 ile karşılaştırılır; bu ek bir karşılaştırma demektir: 5 + 1 = 6.'),
  ('Birçok hızlı sıralama ve birleştirmeli sıralama gerçekleştirmesi, alt dizinin boyu 10–20 elemanın altına inince eklemeli sıralamaya geçer. Bunun nedeni nedir?', 'Küçük boyutlarda eklemeli sıralamanın ek yükü düşük olduğundan pratikte daha hızlı olması', ['Eklemeli sıralamanın büyük dizilerde de n log n sürede çalışması', 'Küçük alt dizilerin birleştirme ya da bölümleme adımlarıyla hiçbir zaman sıralanamaması', 'Eklemeli sıralamanın kararsız olması nedeniyle sonucu dengelemesi'], 'Asimptotik üstünlük büyük n\'de belirgindir; birkaç elemanlık dizilerde özyineleme ve bölümleme maliyeti, eklemeli sıralamanın basit döngüsünden pahalıya gelir.'),
  ('Eklemeli sıralamada yeni eleman sola doğru her adımda komşusuyla takas edilerek değil, büyük elemanlar sağa kaydırılıp en sonda boşluğa yazılarak yerleştiriliyor. Bu yöntemin kazancı nedir?', 'Her adımda üç atama yerine tek atama yapılır', ['Karşılaştırma sayısı her durumda yarı yarıya azalır', 'Algoritma kararsız hâle gelir', 'Ek olarak n elemanlık dizi gerekir'], 'Takas her seferinde geçici değişkenle üç atama ister. Kaydırmada eleman bir kez geçici değişkene alınır, her adımda bir atama yapılır ve en sonda yerine yazılır.'),
  ('Kütüphane sıralaması (library sort) eklemeli sıralamayı hangi fikirle hızlandırır?', 'Diziye boşluklar bırakarak yeni elemanların az kaydırmayla yerleşmesini sağlar', ['Elemanları önce kitap türlerine göre kovalara dağıtır', 'Her yeni elemanı listenin sonuna ekleyip ardından listenin tamamını ters çevirir', 'Elemanları rastgele karıştırıp sonra seçmeli sıralama yapar'], 'Kütüphane raflarında kitaplar arasında boşluk bırakılması gibi, dizide aralıklı boş yerler tutulur; ekleme sırasında kaydırma gereği azalır ve beklenen süre O(n log n)\'e iner.'),
  ('Bir kart oyuncusu elindeki kartları eklemeli sıralamayla düzenliyor ve aynı numaralı iki kartın birbirine göre sırasını bozmak istemiyor. Yeni kartı soldaki kartlarla karşılaştırırken hangi kuralla durmalıdır?', 'Kendisinden büyük olmayan ilk karta gelince', ['Kendisinden küçük olmayan ilk karta gelince', 'Kendisine eşit olan ilk kartın da solundaki kartı geçtikten sonra', 'En soldaki karta ulaşınca, her durumda'], 'Eşit karta rastlanınca durulursa yeni kart eşitinin sağında kalır ve sıraları korunur. Eşitlerin önüne geçmek kararlılığı bozar.'),
  ('Knuth\'un Shell sıralaması için önerdiği boşluk dizisi h ← 3h + 1 kuralıyla 1\'den başlayarak üretilir. Bu dizide 40\'tan sonra gelen boşluk kaçtır?', '121', ['80', '120', '364'], 'Dizi 1, 4, 13, 40, 121, 364, … biçimindedir: 3 · 40 + 1 = 121.'),
  ('35, 33, 42, 10, 14, 19, 27, 44 dizisine Shell sıralamasının boşluğu 4 olan turu uygulanıyor (birbirinden 4 uzaklıktaki elemanlar kendi aralarında sıralanıyor). Tur sonunda dizi nasıl olur?', '14, 19, 27, 10, 35, 33, 42, 44', ['10, 14, 19, 27, 33, 35, 42, 44', '14, 19, 27, 44, 35, 33, 42, 10', '33, 35, 10, 42, 14, 19, 27, 44'], 'Alt diziler (35, 14), (33, 19), (42, 27), (10, 44)\'tür. İlk üçü yer değiştirir, sonuncusu zaten sıralıdır.'),
  ('Shell sıralamasında 4-sıralı (birbirinden 4 uzaktaki elemanları sıralı) hâle getirilmiş bir dizi sonra 2 boşluğuyla sıralanıyor. Bu durumda dizinin 4-sıralılığına ne olur?', 'Korunur; dizi hem 2-sıralı hem 4-sıralı olur', ['Bozulur; 4 uzaklıktaki çiftler yeniden karışır', 'Dizi 8-sıralı hâle gelir', 'Dizi ters sıralı hâle gelir'], 'Daha küçük boşlukla sıralama, önceki büyük boşlukla kazanılan düzeni bozmaz. Bu özellik her turun bir öncekinin işini koruduğunu gösterir.'),
  ('Birleştirme adımında iki sıralı dizi en az sayıda karşılaştırmayla hangi durumda birleştirilir?', 'Bir dizinin bütün elemanları ötekinin bütün elemanlarından küçükse', ['İki dizi tamamen aynı elemanlardan oluşuyorsa', 'İki dizinin elemanları birbirini sırayla izliyorsa', 'Dizilerden biri azalan sırada verilmişse'], 'Örneğin 1, 2, 3 ile 4, 5, 6 birleştirilirken yalnız 3 karşılaştırma yapılır; ilk dizi bitince ikincinin kalanı doğrudan kopyalanır.'),
  ('Aşağıdan yukarı (yinelemeli) birleştirmeli sıralama önce komşu tekli elemanları ikili gruplar hâlinde birleştirir. 38, 27, 43, 3, 9, 82, 10 dizisine bu ilk tur uygulanınca sonuç nedir?', '27, 38, 3, 43, 9, 82, 10', ['3, 27, 38, 43, 9, 10, 82', '27, 38, 43, 3, 9, 82, 10', '3, 9, 10, 27, 38, 43, 82'], 'Çiftler (38, 27), (43, 3), (9, 82) kendi içinde sıralanır; eşi olmayan 10 olduğu gibi kalır.'),
  ('Doğal birleştirmeli sıralama, girdide zaten artan sırada olan ardışık parçaları (koşuları) olduğu gibi kullanır. 3, 5, 8, 2, 4, 9, 1, 7 dizisinde kaç koşu vardır?', '3', ['2', '4', '8'], 'Koşular [3, 5, 8], [2, 4, 9] ve [1, 7]\'dir. Birleştirme bu üç parçadan başlar; dizi ne kadar sıralıysa iş o kadar azalır.'),
  ('İki kişinin aynı 10 filmi beğeniye göre sıraladığı listeler karşılaştırılıyor. Birinin sırasına göre dizilen öbürünün listesindeki ters çift sayısı neyi ölçer?', 'İki sıralamanın ne kadar uyuşmadığını', ['Filmlerin ortalama puanını', 'En çok beğenilen filmin hangisi olduğunu', 'Listelerin kaç film içerdiğini'], 'Ters çift, iki kişinin göreli sırasında anlaşamadığı film çiftidir. Sayı 0 ise sıralamalar aynı, en büyük değerdeyse tamamen terstir; Kendall uzaklığı bu fikre dayanır.'),
  ('n elemanlı bir dizideki ters çift sayısını bulmak için her çifti tek tek denetlemek yerine birleştirmeli sıralamanın değiştirilmiş bir biçimini kullanmanın kazancı nedir?', 'Süre n² yerine n log n mertebesine iner', ['Ters çiftlerin her biri ayrı ayrı listelenmiş olur', 'Dizi sıralanmadan sonuç bulunur', 'Ek bellek gereksinimi tamamen ortadan kalkar'], 'Birleştirme sırasında sol tarafta kalan eleman sayısı toplu olarak eklendiği için çiftler tek tek sayılmaz; böylece karesel sayıda olabilen ters çift n log n sürede sayılır.'),
  ('Her biri sıralı k listenin toplam N elemanı, en küçük başları tutan bir min-yığın (heap) yardımıyla tek bir sıralı listede birleştiriliyor. Bu işlemin süresi hangi mertebededir?', 'N log k', ['N log N', 'N · k', 'k log N'], 'Yığında en fazla k eleman bulunur; her çıktı elemanı için bir çıkarma ve bir ekleme log k sürer. N eleman için toplam N log k olur.'),
  ('Her biri m elemanlı 8 sıralı liste birleştirilecek. Listeleri tek tek birikimli olarak birleştirmek (1 ile 2\'yi, sonucu 3 ile, …) yerine turnuva gibi ikişer ikişer birleştirmenin (4 çift, sonra 2 çift, sonra 1) üstünlüğü nedir?', 'Her eleman yalnız log₂ 8 = 3 birleştirmeden geçer', ['Elemanlar hiç karşılaştırılmadan birleştirilir', 'Toplam iş listelerden yalnız birinin boyuna bağlı kalır', 'Birikimli yöntem yanlış sonuç verirken bu yöntem doğrudur'], 'Birikimli yöntemde ilk listenin elemanları 7 kez kopyalanır ve toplam iş k²·m mertebesine çıkar. İkişerli birleştirmede her eleman 3 düzeyden geçer; iş m·k·log k olur.'),
  ('Lomuto bölümlemesi 7, 2, 9, 4, 5 dizisinde son elemanı (5) pivot alıyor. Bölümleme bitince pivot 0\'dan sayılan hangi indise yerleşir?', '2', ['1', '3', '4'], 'Pivottan küçük ya da eşit iki eleman (2 ve 4) vardır; bu yüzden pivot 2 numaralı indise gider ve dizi 2, 4, 5, 7, 9 olur.'),
  ('Lomuto bölümlemesi sürerken j taranan konum, i ise küçükler bölgesinin son indisiyse hangi değişmez her adımda korunur?', 'a[alt..i] pivottan büyük değildir, a[i+1..j−1] pivottan büyüktür', ['a[alt..i] pivottan büyüktür, a[i+1..j−1] pivottan küçüktür', 'a[alt..j] tamamen sıralıdır ve pivot her adımda a[i] konumunda bekler', 'a[i] ile a[j] her adımda birbirine eşittir'], 'j ilerlerken pivottan küçük ya da eşit bir eleman bulunursa i bir artırılıp takas yapılır; böylece iki bölge sınırları korunarak büyür.'),
  ('Hoare bölümlemesi ile Lomuto bölümlemesi arasındaki önemli farklardan biri hangisidir?', 'Hoare bölümlemesinde pivot bölümleme sonunda kesin yerinde olmak zorunda değildir', ['Hoare bölümlemesi pivotu her zaman dizinin tam ortasına yerleştirir', 'Hoare bölümlemesi ek bir yardımcı dizi kullanır, Lomuto ise tamamen yerinde çalışan bir yöntemdir', 'Hoare bölümlemesi yalnız sıralı dizilerde doğru sonuç verir'], 'Hoare yöntemi diziyi \'pivottan küçük ya da eşitler\' ve \'büyük ya da eşitler\' diye iki parçaya ayırır; pivot bu parçalardan birinin içinde kalabilir. Özyineleme bu yüzden [alt..j] ve [j+1..üst] üzerinde yapılır.'),
  ('\'Üçün ortancası\' pivot seçimi dizinin ilk, ortadaki ve son elemanının ortancasını pivot yapar. 8, 3, 1, 9, 5, 7, 2 dizisinde (ortadaki eleman 0\'dan sayılan 3 numaralı indisteki) hangi değer pivot seçilir?', '8', ['9', '2', '5'], 'İlk eleman 8, ortadaki 9, son eleman 2\'dir. Bu üç değerin ortancası 8\'dir.'),
  ('Üçün ortancası pivot seçiminin, ilk elemanı pivot almaya göre en belirgin kazancı hangisidir?', 'Sıralı ya da ters sıralı girdilerde karesel süreye düşmeyi önler', ['Hızlı sıralamayı kararlı bir algoritmaya dönüştürür', 'En kötü durumda bile, her türlü girdi için n log n süreyi kesin olarak garanti eder', 'Bölümleme sırasında hiç takas yapılmamasını sağlar'], 'Sıralı dizide ilk eleman en küçüktür ve bölümleme dengesiz olur; ilk, orta ve son elemanın ortancası ise gerçek ortancayı verir. Yine de özel olarak hazırlanmış kötü girdiler bulunabilir.'),
  ('İlk elemanı pivot alan basit hızlı sıralama 100 000 elemanlı, zaten sıralı bir diziyle çağrılınca program \'yığın taşması\' hatasıyla çöküyor. Bunun nedeni nedir?', 'Özyineleme derinliği eleman sayısı kadar büyür', ['Dizi bellekte iki kez kopyalanır', 'Karşılaştırma sayısı tam sayı sınırını aşar ve sayaç taşar', 'Sıralı dizide bölümleme döngüsü hiç bitmez'], 'Her bölümleme bir tarafı boş bıraktığından iç içe yaklaşık 100 000 çağrı oluşur; her çağrı yığında yer tuttuğundan çağrı yığını dolar.'),
  ('Hızlı sıralamada her bölümlemeden sonra küçük parça için özyinelemeli çağrı yapılıp büyük parça döngüyle işlenirse ne kazanılır?', 'En kötü durumda bile yığın derinliği log n mertebesinde kalır', ['Toplam karşılaştırma sayısı her girdide n mertebesine iner', 'Algoritma kararlı hâle gelir', 'En kötü durumdaki süre n log n olur'], 'Özyinelemeye giren parça her seferinde en fazla yarı boyutta olduğundan iç içe çağrı sayısı log₂ n\'yi aşamaz; süre ise yine pivot seçimine bağlıdır.'),
  ('Üç yollu bölümleme diziyi \'pivottan küçük\', \'pivota eşit\' ve \'pivottan büyük\' parçalara ayırır. 4, 9, 4, 1, 4, 7 dizisinde pivot 4 ise bölümlemeden sonra kaç eleman özyinelemeli çağrılara girer?', '3', ['5', '6', '2'], 'Küçükler 1, büyükler 9 ve 7\'dir; üç tane 4 zaten son yerindedir ve özyinelemeye girmez. Toplam 1 + 2 = 3 eleman işlenmeye devam eder.'),
  ('Çok sayıda tekrar eden değer içeren (ör. yalnız birkaç farklı not değeri olan) büyük bir dizide üç yollu bölümlemeli hızlı sıralamanın üstünlüğü nedir?', 'Pivota eşit bütün elemanlar bir kerede yerleşir ve bir daha işlenmez', ['Eşit elemanlar birleştirilerek dizinin boyu kalıcı olarak küçültülür ve bellekte yer kazanılır', 'Algoritma eşit değerleri karşılaştırmadan sayma sıralamasına dönüşür', 'Her bölümlemede pivot olarak dizinin en büyük elemanı seçilir'], 'İki yollu bölümlemede eşit elemanlar özyinelemede tekrar tekrar karşılaştırılır. Üç yollu bölümlemede eşitler orta blokta toplanır; farklı değer sayısı az ise süre neredeyse doğrusala iner.'),
  ('Java 7 ile birlikte ilkel tür dizileri için Arrays.sort\'ta kullanılmaya başlanan hızlı sıralama türü hangisidir?', 'Çift pivotlu hızlı sıralama', ['Tek pivotlu, son elemanı pivot alan hızlı sıralama', 'Rastgele pivotlu özyinelemesiz hızlı sıralama', 'Üç pivotlu ve kararlı hızlı sıralama'], 'Vladimir Yaroslavskiy\'nin önerdiği çift pivotlu sürüm iki pivotla diziyi üç parçaya ayırır; ilkel türlerde kararlılık gerekmediği için bu hızlı yöntem seçilmiştir.'),
  ('n elemanlı bir diziden yığın kurmak için elemanları tek tek boş yığına eklemek yerine aşağıdan yukarı süzme (heapify) kullanılırsa kurulum süresi nasıl değişir?', 'n log n yerine n mertebesine iner', ['n yerine n log n mertebesine çıkar', 'Süre değişmez, yalnız bellek azalır', 'n² mertebesinden n log n\'e iner'], 'Düğümlerin çoğu yapraklara yakındır ve az aşağı süzülür; yükseklikler toplamı O(n)\'dir. Tek tek eklemede ise her ekleme log n sürebilir.'),
  ('10 elemanlı bir diziden aşağıdan yukarı max-yığın kurulurken (indisler 0\'dan) süzme işlemine hangi indisten başlanır?', '4', ['5', '9', '0'], '⌊n/2⌋ − 1 = 4\'ten sonraki bütün indisler yapraktır ve tek başlarına zaten yığındır. Süzme 4\'ten 0\'a doğru geriye yapılır.'),
  ('Yığın sıralaması en kötü durumda da n log n sürede ve yerinde çalışmasına rağmen pratikte çoğunlukla iyi yazılmış hızlı sıralamadan yavaştır. Bunun başlıca nedeni nedir?', 'Bellekte uzak konumlara atladığı için önbelleği verimsiz kullanması', ['Ek olarak n elemanlık bir dizi gerektirmesi', 'Sıralı ya da ters sıralı girdilerde her zaman karesel süreye düşmesi', 'Yalnız tam sayı dizilerinde kullanılabilmesi'], 'Süzme işlemi i\'den 2i + 1\'e atlar; büyük dizilerde bu erişimler önbellekte bulunmaz. Hızlı sıralama ise ardışık bellek bölgelerini tarar.'),
  ('Dijkstra\'nın 1981\'de önerdiği ve neredeyse sıralı girdilerde doğrusala yaklaşan, yığın sıralamasının uyarlanabilir türü olan algoritma hangisidir?', 'Smoothsort', ['Timsort', 'Shellsort', 'Introsort'], 'Smoothsort, Leonardo sayılarına dayalı yığınlar kullanır; en kötü durumda n log n, sıralı girdide ise O(n) sürede çalışır.'),
  ('7, 2, 9, 4, 5 dizisinde 3. en küçük eleman hızlı seçmeyle aranıyor. İlk bölümlemede son eleman (5) pivot alınıyor ve dizi 2, 4, 5, 7, 9 oluyor. Algoritma ne yapar?', 'Pivot 3. konuma yerleştiği için 5\'i sonuç olarak döndürür', ['Sol taraf olan 2, 4\'te aramayı sürdürür', 'Sağ taraf olan 7, 9\'da aramayı sürdürür', 'Diziyi tamamen sıraladıktan sonra 3. elemana bakar ve 4\'ü döndürür'], 'Pivottan küçük iki eleman olduğu için pivot 3. sıradaki elemandır; aranan sıra numarasıyla eşleştiğinden başka bölümleme gerekmez.'),
  ('Bir sınıftaki 1000 öğrencinin puanlarının ortancasını bulmak için diziyi tamamen sıralamak yerine hızlı seçme kullanmanın kazancı nedir?', 'Ortalamada n log n yerine n mertebesinde işlem yapılır', ['Bulunan ortanca, tam sıralamayla bulunan ortancadan daha doğru olur', 'Puanlar kalıcı olarak sıralı hâle gelir', 'Ek bellek gereği n² mertebesinden n\'ye iner'], 'Ortanca, 500. (ve 501.) en küçük elemandır; sırayla ilgili tek gereken bilgi budur. Hızlı seçme yalnız gereken tarafla ilgilenerek bütün diziyi sıralamaktan kaçınır.'),
  ('Sayma sıralaması 2, 0, 2, 3, 0, 1 dizisine uygulanıyor (değerler 0–4). Sayaç dizisi [2, 1, 2, 1, 0] bulunduktan sonra birikimli (önek) toplamları alınırsa dizi ne olur?', '[2, 3, 5, 6, 6]', ['[2, 1, 2, 1, 0]', '[0, 2, 3, 5, 6]', '[6, 4, 3, 1, 0]'], 'Her değer kendinden öncekilerin toplamına eklenir: 2, 2+1 = 3, 3+2 = 5, 5+1 = 6, 6+0 = 6. Her sayı, o değere kadar olan elemanların toplam sayısını gösterir.'),
  ('Sayma sıralamasında birikimli sayaç dizisi [2, 3, 5, 6, 6] (değerler 0–4) iken girdi sondan başa taranıyor. Karşılaşılan ilk 2 değeri çıktıda (indisler 0\'dan) hangi konuma yazılır?', '4', ['5', '2', '3'], '2 için birikimli sayaç 5\'tir; bu değer bir azaltılır ve eleman 4 numaralı konuma yazılır. Sonraki 2 ise 3 numaralı konuma düşer.'),
  ('Değerleri 0 ile 1 milyar arasında olabilen yalnız 10 sayıyı sıralamak için sayma sıralaması neden uygun değildir?', 'Sayaç dizisi değer aralığı kadar büyük olacağından bellek ve zaman boşa gider', ['Sayma sıralaması yalnız tek basamaklı sayılarla çalışabilir', 'Bu kadar az elemanla sayma sıralaması kararsız hâle gelir ve eşit değerler karışır', 'Büyük sayılarda karşılaştırma sayısı hızla artar'], 'Sayma sıralamasının süresi ve belleği O(n + k)\'dır; burada k değer aralığıdır. k = 10⁹ iken n = 10 için bu son derece verimsizdir.'),
  ('Değerleri −3 ile 2 arasında olan bir tam sayı dizisi sayma sıralamasıyla sıralanacak. Sayaç dizisinde değer v\'nin sayacı hangi indiste tutulmalıdır?', 'v + 3', ['v − 3', '|v|', 'v'], 'En küçük değer (−3) 0 numaralı indise denk gelmelidir; bu yüzden her değere 3 eklenerek kaydırılır ve 6 gözlü bir sayaç dizisi yeterli olur.'),
  ('Bir arşivde gün.ay.yıl biçimindeki tarihler kronolojik sıraya konacak. Kararlı bir sıralamayla üç geçiş yapılacaksa geçişler hangi sırayla yapılmalıdır?', 'Önce güne, sonra aya, en son yıla göre', ['Önce yıla, sonra aya, en son güne göre', 'Önce aya, sonra güne, en son yıla göre', 'Önce yıla, sonra güne, en son aya göre'], 'LSD taban sıralamasında olduğu gibi en az önemli alandan başlanır. Son geçiş yıla göre yapıldığından aynı yıldaki tarihler önceki geçişlerin sırasını (ay, sonra gün) korur.'),
  ('Taban sıralamasının çalışma süresi O(d · (n + b)) ile verilir. Bu ifadede d ve b neyi gösterir?', 'd basamak sayısını, b tabanı', ['d dizideki farklı değer sayısını, b ise dizinin bellekte bayt cinsinden kapladığı boyutu', 'd dizinin derinliğini, b karşılaştırma sayısını', 'd en büyük değeri, b en küçük değeri'], 'Her biri n + b süren d geçiş yapılır; b sayaç dizisinin boyudur. d ve b sabitse süre n ile doğru orantılı olur.'),
  ('Kova sıralamasında her kovanın kendi içinde sıralanması için genellikle eklemeli sıralama seçilmesinin gerekçesi nedir?', 'Düzgün dağılımda kovalar birkaç elemanlık kalır ve küçük dizilerde eklemeli sıralama çok hızlıdır', ['Eklemeli sıralama kovaları birbirine bağlamak için gereken tek algoritma olduğu için', 'Eklemeli sıralama kovaların içeriğini değiştirmeden sıraladığı için', 'Kova içinde başka bir algoritma kullanılırsa sonuç her zaman kararsız ve yanlış olacağı için'], 'Beklenen kova boyu sabit olduğundan eklemeli sıralamanın düşük ek yükü öne çıkar ve kararlılığı da korunur.'),
  ('Bir permütasyonu yalnız takaslarla sıralamak için gereken en az takas sayısı, eleman sayısından permütasyondaki döngü sayısı çıkarılarak bulunur. 2, 3, 1, 5, 4 dizisi en az kaç takasla sıralanır?', '3', ['2', '4', '5'], 'Döngüler (1 → 2 → 3 konumları) ve (4 ↔ 5) olmak üzere 2 tanedir. 5 − 2 = 3 takas yeter: üçlü döngü 2, ikili döngü 1 takasla düzelir.'),
  ('Döngü sıralaması bir elemanın son konumunu, dizide ondan küçük eleman sayısını sayarak bulur. 7, 2, 9, 4, 5 dizisinde 7 değeri (indisler 0\'dan) hangi konuma yazılır?', '3', ['0', '4', '2'], '7\'den küçük elemanlar 2, 4 ve 5\'tir; üç tane olduğundan 7\'nin sıralı dizideki indisi 3\'tür.'),
  ('Gözleme sıralamasında yapılabilen tek işlem, yığının üstünden belli sayıda gözlemeyi spatulayla ters çevirmektir. Üstten alta 3, 1, 2 olan yığında (en büyük en alta gelecek biçimde) önce en büyüğü tepeye, sonra yerine çeviren basit yöntem kaç çevirme yapar?', '2', ['3', '1', '4'], '3 zaten tepededir; bütün yığın çevrilince 2, 1, 3 olur. Kalan üst ikili içinde en büyük (2) tepededir; iki gözleme çevrilince 1, 2, 3 elde edilir.'),
  ('Gözleme sıralamasında her turda kalanların en büyüğünü önce tepeye, sonra yerine getiren basit yöntem n gözlemeyi en fazla kaç çevirmeyle sıralar?', '2n − 3', ['n − 1', 'n²', 'n log n'], 'Her gözleme için en fazla iki çevirme gerekir; son iki gözleme için toplam en fazla bir çevirme yeterli olduğundan üst sınır 2(n − 2) + 1 = 2n − 3\'tür.'),
  ('Bogo sıralaması diziyi rastgele karıştırır ve sıralı olup olmadığına bakar; sıralı değilse yeniden karıştırır. Birbirinden farklı 4 elemanlı bir dizi için beklenen karıştırma sayısı kaçtır?', '24', ['4', '16', '256'], 'Her karıştırma 4! = 24 dizilişten birini eşit olasılıkla üretir ve yalnız biri sıralıdır. Başarı olasılığı 1/24 olduğundan beklenen deneme sayısı 24\'tür.'),
  ('\'Uyku sıralaması\' şakası her sayı için ayrı bir iş parçacığı başlatır; her parçacık sayının değeri kadar saniye bekleyip sayıyı yazar. Bu yöntem neden güvenilir bir sıralama değildir?', 'Sonuç işletim sisteminin zamanlamasına bağlıdır ve yakın değerler karışabilir', ['Yazılan sayılar her zaman büyükten küçüğe sıralı çıkar ve ters çevrilmesi gerekir', 'Sayılar birbirleriyle karşılaştırıldığı için n² süre alır', 'Her sayı iki kez yazıldığı için sonuç iki katı uzunlukta olur'], 'Parçacıkların ne zaman uyanıp çalışacağı zamanlayıcıya bağlıdır; 1,000 ile 1,001 gibi yakın değerler yer değiştirebilir. Negatif sayılar da işlenemez ve süre en büyük değere bağlıdır.'),
  ('Bir tahta yüzeye dikilen farklı boylardaki çubuklardan, üstten bir el indirilerek ilk dokunulanın en uzun olarak alınması ile çalışan düşünce deneyindeki \'spagetti sıralaması\' neyi göstermeye yarar?', 'Fiziksel paralellikle her seçimin tek adımda yapılabildiği bir sıralama modelini', ['Karşılaştırmalı sıralamanın her zaman n² süre aldığını', 'Rastgele karıştırmanın, yeterince deneme yapılırsa en hızlı sıralama yöntemi olduğunu', 'Uzun dizilerin kısa dizilerden önce sıralanması gerektiğini'], 'Her çubuk boyunu aynı anda \'karşılaştırır\'; el en uzununa ilk dokunur. Bu, sıradan bilgisayar modelinin dışında kalan analog bir paralel hesaplama örneğidir.'),
  ('Sıralama ağlarının doğruluğunu sınamakta kullanılan \'0-1 ilkesi\' neyi söyler?', 'Ağ yalnız 0 ve 1\'lerden oluşan bütün girdileri sıralıyorsa her girdiyi sıralar', ['Ağdaki karşılaştırıcı sayısı 0 ya da 1 olmalıdır', 'Ağ yalnız ikilik tabanda yazılmış sayıları sıralayabilir; onluk sayılar önce dönüştürülmelidir', 'Bir girdide 0\'lar sayılınca ağın derinliği bulunur'], 'Bu ilke sayesinde n girişli bir ağın doğruluğu, sonsuz sayıdaki girdi yerine yalnız 2ⁿ tane 0-1 dizisiyle denetlenebilir.'),
  ('Bir sıralama ağının \'derinliği\' paralel donanımda neyi belirler?', 'Aynı anda çalışabilen karşılaştırıcılar katmanlara ayrıldığında gereken adım sayısını', ['Ağdaki toplam karşılaştırıcı sayısını, katmanlara ayrılıp ayrılmamalarından bağımsız olarak', 'Ağın sıralayabileceği en büyük sayının bit uzunluğunu', 'Ağın kaç farklı girdi sayısıyla çalışabileceğini'], 'Ortak hat paylaşmayan karşılaştırıcılar aynı anda çalışabilir. Derinlik, girdinin ağın başından sonuna kadar geçmesi için gereken paralel adım sayısıdır.'),
  ('Bitonik sıralamanın ekran kartları (GPU) gibi paralel donanımlarda sevilmesinin nedeni hangisidir?', 'Karşılaştırma deseni veriden bağımsız ve düzenli olduğu için', ['Toplam karşılaştırma sayısı bilinen her sıralama algoritmasınınkinden az olduğu için', 'Kararlı olduğu ve eşit elemanları koruduğu için', 'Ek belleğe hiç ihtiyaç duymayan tek algoritma olduğu için'], 'Hangi hatların karşılaştırılacağı önceden bellidir; binlerce çekirdek aynı komutu farklı veri üzerinde dallanmadan çalıştırabilir. Toplam iş n log² n ile biraz fazla olsa da paralellik bunu telafi eder.'),
  ('8 oyunculu bir eleme turnuvasında en iyi oyuncu 7 maçta belirleniyor. İkinci en iyi oyuncuyu bulmak için yalnız kimler arasında ek maç yapılması yeterlidir?', 'Şampiyona doğrudan yenilen 3 oyuncu arasında', ['Finalde kaybeden oyuncu ile ilk turda elenenler arasında', 'Şampiyon dışındaki bütün 7 oyuncu arasında', 'Yarı finalde kaybeden iki oyuncu arasında'], 'İkinci en iyi oyuncu yalnız şampiyona yenilmiş olabilir; başka birine yenilen biri ikinci olamaz. Şampiyon log₂ 8 = 3 maç yaptığından 3 aday vardır ve 2 ek maç yeter.'),
  ('Turnuva yöntemiyle n = 8 elemanlı bir dizide en büyük ve ikinci en büyük eleman birlikte en az kaç karşılaştırmayla bulunur? (Formül: n + ⌈log₂ n⌉ − 2)', '9', ['13', '7', '11'], '8 + 3 − 2 = 9: en büyük için 7, ikinci için şampiyona yenilen 3 aday arasında 2 karşılaştırma. İki ayrı doğrusal tarama ise 7 + 6 = 13 karşılaştırma ister.'),
  ('Timsort\'ta doğal koşu \'minrun\' değerinden (genellikle 32–64 arası) kısaysa ne yapılır?', 'Koşu, ikili eklemeli sıralamayla minrun uzunluğuna tamamlanır', ['Koşu atılır ve elemanları dizinin sonuna eklenir', 'Koşu yığın sıralamasıyla ayrıca sıralanıp bırakılır', 'Koşu hiç değiştirilmeden çok sayıda küçük parça olarak birleştirmeye gönderilir'], 'Kısa koşular sonraki elemanlarla uzatılır ve ikili eklemeli sıralamayla sıralanır; böylece birleştirilecek koşular dengeli boyda olur.'),
  ('İçgözlemli sıralama (introsort) hızlı sıralamayla başlar ve özyineleme derinliği belirli bir sınırı aşınca yığın sıralamasına geçer. Sınır 2·⌊log₂ n⌋ ise n = 1024 için bu sınır kaçtır?', '20', ['10', '1024', '2048'], 'log₂ 1024 = 10 olduğundan sınır 2 · 10 = 20\'dir. Derinlik bunu aşarsa hızlı sıralamanın kötü duruma girdiği anlaşılır ve yığın sıralaması n log n\'i garanti eder.'),
  ('Go dilinin 1.19 sürümünde standart kütüphanedeki kararsız sıralama için benimsenen, kötü girdi desenlerini fark edip önlemler alan hızlı sıralama türevi hangisidir?', 'pdqsort (desen yenen hızlı sıralama)', ['Smoothsort', 'Stooge sıralaması (üçte iki yöntemi)', 'Bitonik sıralama (paralel ağ)'], 'Orson Peters\'in pdqsort algoritması dengesiz bölümlemeleri fark edince pivotu karıştırır ya da yığın sıralamasına geçer; sıralı ve az farklı değerli girdilerde de hızlıdır.'),
  ('Python\'da sorted([\'elma\', \'kivi\', \'muz\', \'armut\'], key=len) ifadesinin sonucu nedir?', '[\'muz\', \'elma\', \'kivi\', \'armut\']', ['[\'muz\', \'kivi\', \'elma\', \'armut\']', '[\'armut\', \'elma\', \'kivi\', \'muz\']', '[\'elma\', \'kivi\', \'muz\', \'armut\']'], 'Sözcükler uzunluklarına göre (3, 4, 4, 5) sıralanır. Python\'un sıralaması kararlı olduğundan eşit uzunluktaki \'elma\' ve \'kivi\' ilk sıralarını korur.'),
  ('Python\'da sorted([(\'a\', 2), (\'b\', 1), (\'c\', 2)], key=lambda t: t[1], reverse=True) ifadesinin sonucu nedir?', '[(\'a\', 2), (\'c\', 2), (\'b\', 1)]', ['[(\'c\', 2), (\'a\', 2), (\'b\', 1)]', '[(\'b\', 1), (\'a\', 2), (\'c\', 2)]', '[(\'c\', 2), (\'b\', 1), (\'a\', 2)]'], 'reverse=True azalan sıralama yapar ama kararlılığı korur: eşit anahtarlı (\'a\', 2) ve (\'c\', 2) özgün sıralarında kalır.'),
  ('C\'de tam sayıları sıralayan bir karşılaştırıcı \'return a − b;\' olarak yazılmış. Hangi girdilerde bu işlev yanlış sonuç verebilir?', 'Fark tam sayı sınırını aşacak kadar büyük ya da küçük değerlerde', ['Yalnız birbirine eşit iki değer karşılaştırıldığında', 'Yalnız iki değer de pozitif olduğunda', 'Dizi tek sayıda eleman içerdiğinde ve ortadaki eleman kendisiyle karşılaştırıldığında'], 'Örneğin a çok büyük pozitif, b çok büyük negatifse a − b taşar ve işareti ters çıkar. Güvenli yazım (a > b) − (a < b) biçimindedir.'),
  ('C++\'ta std::nth_element(v.begin(), v.begin() + k, v.end()) çağrısından sonra hangi özellik garanti edilir?', 'k. konumdaki eleman tam sıralamadaki değerdir; solundakiler ondan büyük değildir', ['Vektörün tamamı artan sırada sıralanmış olur', 'İlk k eleman kendi aralarında sıralı olur, geri kalanların başlangıçtaki sırası ise korunur', 'k. konumdaki eleman vektörün en büyük elemanı olur ve sona taşınır'], 'nth_element hızlı seçme tabanlıdır; ortalama doğrusal sürede yalnız k. konumu doğru yerleştirir ve diziyi bu elemana göre bölümler.'),
  ('Bir öğrenci taş-kâğıt-makas kurallarını (taş makası, makas kâğıdı, kâğıt taşı yener) karşılaştırıcı olarak kullanıp bir hamle listesini sıralamaya çalışıyor. Asıl sorun nedir?', 'Kural geçişli olmadığı için tutarlı bir sıra yoktur', ['Üç farklı değer sıralanamayacak kadar azdır', 'Karşılaştırıcı eşit değerleri hiçbir zaman eşit saymaz', 'Bu kurallarla yalnız yığın sıralaması çalışabilir ve diğerleri hata verir'], 'Taş > makas > kâğıt > taş döngüsü oluşur. Hangi eleman başa gelirse gelsin bir başkası ondan önce gelmeliydi; sıralama algoritmasının sonucu anlamsız ve tutarsız olur.'),
  ('Python\'da [(\'Ece\', 80), (\'Ali\', 90), (\'Can\', 80)] listesi key=lambda t: (−t[1], t[0]) ile sıralanıyor. Sonuç hangisidir?', 'Ali 90, Can 80, Ece 80', ['Ece 80, Can 80, Ali 90', 'Ali 90, Ece 80, Can 80', 'Can 80, Ece 80, Ali 90'], 'Anahtarın ilk öğesi puanın eksisi olduğundan puanlar büyükten küçüğe dizilir; eşit puanlıların ikinci öğesi olan ad alfabetik sırayla karşılaştırılır: Can, Ece\'den önce gelir.'),
  ('Python\'da sorted([−5, 3, −1, 4], key=abs) ifadesinin sonucu nedir?', '[−1, 3, 4, −5]', ['[−5, −1, 3, 4]', '[−1, 3, 4, 5]', '[4, 3, −1, −5]'], 'Anahtar mutlak değerdir: 5, 3, 1, 4. Elemanlar bu değerlere göre dizilir ama kendileri değişmez; sonuç −1, 3, 4, −5 olur.'),
  ('Anahtarı hesaplamak pahalıysa (ör. her öğe için bir dosyanın boyutunu okumak), \'süsle-sırala-süsü kaldır\' (Schwartz dönüşümü) yaklaşımı ne kazandırır?', 'Anahtar her öğe için bir kez hesaplanır, her karşılaştırmada yeniden hesaplanmaz', ['Sıralama algoritması karşılaştırmasız hâle gelir', 'Liste sıralandıktan sonra gerektiğinde tek adımda eski hâline geri döndürülebilir', 'Anahtarlar kalıcı olarak dosya adlarının sonuna yazılır'], 'Her öğe (anahtar, öğe) çiftine dönüştürülür, çiftler sıralanır, sonra öğeler geri alınır. Karşılaştırıcıda hesaplansaydı anahtar n log n kez hesaplanacaktı. Python\'un key parametresi de bu fikre dayanır.'),
  ('Bir klasördeki dosya1, dosya2, dosya10 adlı dosyalar karakter karakter karşılaştırmayla sıralanınca hangi sıra oluşur?', 'dosya1, dosya10, dosya2', ['dosya1, dosya2, dosya10', 'dosya10, dosya1, dosya2', 'dosya2, dosya10, dosya1'], '\'1\' ile başlayan \'10\', \'2\'den önce gelir. Sayıların değerine göre sıralayan \'doğal sıralama\' için ad içindeki sayı kısımları sayı olarak karşılaştırılmalıdır.'),
  ('\'Zeytin\', \'Çiçek\' ve \'Armut\' sözcükleri Unicode kod noktalarına göre (yerel dil kuralı uygulanmadan) sıralanırsa sonuç nedir?', 'Armut, Zeytin, Çiçek', ['Armut, Çiçek, Zeytin', 'Çiçek, Armut, Zeytin', 'Zeytin, Çiçek, Armut'], '\'Ç\' harfinin kod noktası (U+00C7) İngiliz alfabesindeki \'Z\'den (U+005A) büyüktür. Türkçe alfabetik sıra için dile duyarlı karşılaştırma (collation) kullanılmalıdır.'),
  ('Yazılım sürüm numaraları \'1.9\' ve \'1.10\' metin olarak karşılaştırılırsa hangi hata oluşur?', '\'1.10\', \'1.9\'dan önce gelir; oysa daha yeni sürümdür', ['İkisi eşit sayılır ve sıra rastgele olur', '\'1.9\' sayıya çevrilemediği için hata oluşur', '\'1.10\' her zaman listenin sonuna yerleşir ve sonuç beklenen sürüm sırasıyla aynı çıkar'], 'Karakter karşılaştırmasında \'1\' < \'9\' olduğundan \'1.10\' önce gelir. Doğru sıralama için noktayla ayrılan her parça ayrı bir tam sayı olarak karşılaştırılmalıdır.'),
  ('Dış sıralamada 100 sıralı koşu var ve bellek aynı anda en fazla 10 koşuyu birleştirmeye yetiyor. Tek bir sıralı dosya elde etmek için kaç birleştirme turu gerekir?', '2', ['1', '10', '5'], 'İlk turda 10\'arlı gruplar birleşir ve 10 koşu kalır; ikinci turda bu 10 koşu tek dosyada birleşir. Gereken tur sayısı ⌈log₁₀ 100⌉ = 2\'dir.'),
  ('Kararlı olmayan bir sıralama algoritmasını kararlı biçimde kullanmanın genel bir yolu hangisidir?', 'Her elemanın başlangıç indisini anahtara ikinci ölçüt olarak eklemek', ['Diziyi sıralamadan önce ters çevirmek', 'Eşit elemanları diziden çıkarıp en sona eklemek', 'Algoritmayı iki kez art arda çalıştırıp sonuçları karşılaştırmak ve gerekirse düzeltmek'], 'Anahtar (değer, indis) çiftine dönüşünce hiçbir iki eleman eşit kalmaz; eşit değerliler indislerine göre dizilir ve özgün sıra korunur. Bedeli ek bellektir.'),
  ('Aşağıdakilerden hangisi hem kararlı hem de standart biçimiyle yerinde çalışan bir sıralama algoritmasıdır?', 'Eklemeli sıralama', ['Birleştirmeli sıralama', 'Yığın sıralaması', 'Hızlı sıralama'], 'Eklemeli sıralama yalnız sabit ek bellek kullanır ve eşitleri birbirinin önüne geçirmez. Birleştirmeli sıralama kararlıdır ama ek dizi ister; yığın ve hızlı sıralama yerinde ama kararsızdır.'),
  ('[1, 3], [2, 6], [8, 10], [9, 12] aralıkları başlangıç noktalarına göre sıralanıp çakışanlar birleştiriliyor. Sonuç hangisidir?', '[1, 6] ve [8, 12]', ['[1, 12]', '[1, 3], [2, 6] ve [8, 12]', '[1, 6], [8, 10] ve [9, 12]'], 'Sıralı aralıklarda her aralık bir öncekinin bitişiyle karşılaştırılır: [2, 6], [1, 3] ile çakışır ve [1, 6] olur; [9, 12], [8, 10] ile çakışır ve [8, 12] olur.'),
  ('(0, 30), (5, 10), (15, 20) saatlerinde üç toplantı var. Başlangıç ve bitiş saatleri ayrı ayrı sıralanıp zaman çizgisi taranarak aynı anda gereken en çok salon sayısı bulunuyor. Sonuç kaçtır?', '2', ['1', '3', '30'], 'Sıralı başlangıçlar 0, 5, 15; bitişler 10, 20, 30\'dur. 5\'te iki toplantı sürer, 10\'da biri biter, 15\'te yeni biri başlar; aynı anda en fazla 2 toplantı vardır.'),
  ('Yarışmada puanlar 90, 85, 85, 70 olarak büyükten küçüğe sıralanmış. Sıra numarası \'kendisinden kesin yüksek puan alanların sayısı + 1\' olarak verilirse 70 puan alan yarışmacının sırası kaçtır?', '4', ['3', '2', '5'], '70\'ten yüksek puan alan üç kişi vardır (90, 85, 85); 3 + 1 = 4. Eşit puanlı ikisi 2. sırayı paylaştığı için 3. sıra boş kalır.'),
  ('Milyonlarca kayıt içinden en yüksek puanlı 10 kaydı bulmak için boyutu 10 olan bir yığın kullanılıyor. Bu yığın hangi türde olmalıdır ve neden?', 'Min-yığın; çünkü en küçük aday kökte olur ve hızla değiştirilebilir', ['Max-yığın; çünkü en büyük kayıt her zaman kökte durur ve korunur', 'Min-yığın; çünkü yalnız min-yığına eleman eklenebilir', 'Max-yığın; çünkü min-yığın 10\'dan fazla eleman tutamaz ve taşma olur'], 'Yeni kayıt, şimdiye dek bulunan 10 adayın en küçüğünden büyükse onun yerine geçmelidir. En küçüğü kökte tutan min-yığın bu denetimi O(1), değiştirmeyi O(log 10) sürede yapar.'),
  ('n elemanlı bir veri akışından en büyük k elemanı boyutu k olan bir yığınla seçmenin süresi hangi mertebededir?', 'n log k', ['n log n', 'n · k', 'k log n'], 'Her eleman için en fazla bir yığın işlemi yapılır ve yığının boyu k\'yi geçmez; k küçükse bu yöntem bütün veriyi sıralamaktan çok daha hızlıdır.'),
  ('\'Kısmi hızlı sıralama\' en küçük k elemanı sıralı olarak bulmak için hızlı sıralamayı nasıl değiştirir?', 'Yalnız ilk k konumla kesişen parçalara özyineleme yapar', ['Pivotu her zaman k. eleman olarak seçer ve bölümleme yapmaz', 'Bölümlemeyi yalnız sağ tarafta yapar, sol tarafı bırakır', 'Diziyi k parçaya bölüp her parçanın en küçüğünü alır ve birleştirir'], 'Pivotun sağında kalan ve tamamen k\'nin ötesindeki parçalar hiç sıralanmaz; böylece ortalama süre n + k log k mertebesine iner.'),
  ('C++\'taki std::partial_sort(v.begin(), v.begin() + k, v.end()) çağrısının sonucu hangisidir?', 'En küçük k eleman başa sıralı yerleşir; kalanların sırası belirsizdir', ['Vektörün tamamı sıralanır, k yalnız hız ayarıdır', 'İlk k eleman olduğu gibi kalır, geri kalanı sıralanır', 'Vektör k eşit parçaya bölünür ve her parça kendi içinde ayrı ayrı sıralanır'], 'partial_sort genellikle yığın tabanlıdır ve n log k sürede çalışır; aralığın geri kalanındaki elemanlar herhangi bir sırada bırakılabilir.'),
  ('Birleştirmeli sıralama 1 milyon elemanı 1 saniyede sıralıyor. 2 milyon eleman için süre yaklaşık ne kadar olur?', 'Yaklaşık 2,1 saniye', ['Yaklaşık 4 saniye', 'Tam 1 saniye', 'Yaklaşık 1,05 saniye'], 'n log n büyümede oran (2·10⁶ · log 2·10⁶)/(10⁶ · log 10⁶) ≈ 2 · 20,9/19,9 ≈ 2,1\'dir; süre iki katın biraz üstüne çıkar.'),
  ('Bir sıralama işlemi yarıda kesilirse dizinin başındaki elemanların kesin sonuç olması, yani en küçük elemanlar olarak doğru yerlerinde durması isteniyor. Basit algoritmalardan hangisi bu özelliği her adımda sağlar?', 'Seçmeli sıralama', ['Eklemeli sıralama', 'Birleştirmeli sıralama', 'Kabarcık sıralamasının soldan sağa standart biçimi'], 'Seçmeli sıralamada her adımda kalanların en küçüğü başa yerleşir ve bir daha değişmez. Eklemeli sıralamada baş kısım sıralıdır ama sonra gelen elemanlarla kayabilir; standart kabarcık ise dizinin sonunu kesinleştirir.'),
  ('Z-algoritmasıyla bir metinde kalıp aranırken kalıp, metnin başına özel bir ayırıcı karakterle (ör. \'kalıp\$metin\') eklenir. Eşleşme hangi konumlarda vardır?', 'Z değeri kalıbın uzunluğuna eşit olan konumlarda', ['Z değeri sıfır olan konumlarda', 'Z değeri en büyük olan tek konumda', 'Z değeri metnin uzunluğuna eşit olan konumlarda ve ayırıcının hemen sonrasında'], 'Z değeri kalıbın uzunluğu m\'ye ulaşan konumda kalıbın tamamı eşleşmiştir. Ayırıcı, eşleşmenin m\'yi aşmasını önler. Toplam süre doğrusaldır.'),
  ('Yığın sıralamasının bağlı liste üzerinde pratik olmamasının nedeni hangisidir?', 'i. düğümün çocuklarına (2i + 1, 2i + 2) hızla erişmek için rastgele erişim gerekir', ['Bağlı listede elemanlar karşılaştırılamaz', 'Yığın sıralaması yalnız sayılarla çalışır', 'Bağlı listede takas yapmak için listenin tamamen kopyalanması gerekir'], 'Dizi tabanlı yığın, indis aritmetiğiyle sabit sürede çocuklara ulaşır. Bağlı listede her erişim baştan yürümeyi gerektirir ve algoritma çok yavaşlar.'),
  ('\'banana\' sözcüğünün bütün sonekleri sözlük sırasına dizilerek sonek dizisi kuruluyor. Sıralı listede ikinci sırada hangi sonek bulunur?', 'ana', ['a', 'anana', 'banana'], 'Sonekler sıralanınca a, ana, anana, banana, na, nana elde edilir. Sonek dizisinde bunların başlangıç indisleri [5, 3, 1, 0, 4, 2] olarak tutulur.'),
  ('Bir metin düzenleyicide \'tümünü değiştir\' işlemi, kalıbın bütün eşleşmelerini soldan sağa arayıp değiştiriyor ve her eşleşmeden sonra aramaya eşleşmenin sonundan devam ediyor. \'ababab\' metninde \'aba\' yerine \'X\' yazılırsa sonuç ne olur?', 'Xbab', ['XX', 'XbX', 'ababab'], 'İlk eşleşme 0. konumdadır ve \'aba\' değiştirilince arama 3. konumdan sürer; kalan \'bab\' içinde \'aba\' yoktur. Örtüşen 2. konumdaki eşleşme bu yüzden atlanır.'),
  ('Sabır sıralamasında kartlar sırayla dağıtılır: her kart, tepesindeki kart kendisinden küçük olmayan en soldaki yığına konur; böyle yığın yoksa sağa yeni yığın açılır. 4, 2, 7, 3, 8, 1, 5 kartları dağıtılınca yığınların tepelerinde soldan sağa hangi kartlar bulunur?', '1, 3, 5', ['4, 7, 8', '2, 3, 5', '1, 2, 3, 5'], '4 → [4]; 2 → [2]; 7 → [2, 7]; 3 → [2, 3]; 8 → [2, 3, 8]; 1 → [1, 3, 8]; 5 → [1, 3, 5]. Yığın sayısı (3) en uzun artan alt dizinin uzunluğuna eşittir.'),
  ('Sabır sıralamasında yığınların tepe kartları soldan sağa her zaman artan sıradadır. Bu özellik algoritmada nasıl kullanılır?', 'Yeni kartın konacağı yığın ikili aramayla bulunur', ['Kartlar yığınlara rastgele dağıtılabilir', 'En sağdaki yığın her zaman boş bırakılır', 'Yığın sayısı her zaman kart sayısının yarısına eşit tutulur'], 'Tepe kartlar sıralı olduğundan uygun yığın doğrusal tarama yerine O(log n) sürede bulunur; böylece en uzun artan alt dizi uzunluğu n log n sürede hesaplanır.'),
  ('Bir telefon rehberi uygulaması alfabetik sıralı kişi listesinde \'Ay\' ile başlayan bütün adları gösterecek. En verimli yöntem hangisidir?', '\'Ay\' için alt sınır ile \'Az\' için alt sınır arasındaki bloğu almak', ['Listeyi baştan sona tarayıp her adın ilk iki harfine bakmak', '\'Ay\' için tek bir ikili arama yapıp yalnız bulunan adı göstermek', 'Listeyi \'Ay\' önekine göre yeniden sıralayıp en baştaki adları göstermek'], 'Aynı önekle başlayan adlar sıralı listede ardışık bir blok oluşturur. İki ikili arama bloğun sınırlarını O(log n) sürede bulur.'),
  ('Bir oyunun sıralı skor tablosunda yalnız bir oyuncunun puanı artıyor. Tabloyu yeniden düzene sokmanın en verimli yolu hangisidir?', 'Oyuncuyu, yerini bulana kadar komşularıyla yer değiştirerek yukarı taşımak', ['Tablonun tamamını birleştirmeli sıralamayla baştan sıralamak', 'Tabloyu ters çevirip ikili aramayla oyuncuyu bulmak', 'Bütün oyuncuları tablodan silip tabloyu boş bir listeden yeni puanlarla baştan yeniden kurmak'], 'Tablonun geri kalanı zaten sıralıdır; tek bir elemanın yeri eklemeli sıralamadaki gibi en fazla n adımda düzeltilir, n log n\'lik tam sıralamaya gerek yoktur.'),
  ('Belleği çok kısıtlı ve en kötü durumda bile yanıt süresinin garanti edilmesi gereken bir gömülü sistemde aşağıdaki sıralama algoritmalarından hangisi en uygundur?', 'Yığın sıralaması', ['Birleştirmeli sıralama', 'Basit hızlı sıralama', 'Bogo sıralaması'], 'Yığın sıralaması yerinde çalışır (sabit ek bellek) ve en kötü durumda da n log n sürede biter. Birleştirmeli sıralama ek bellek ister; hızlı sıralama ise en kötü durumda karesel olabilir.'),
  ('Hiç değişmeyen 50 000 elemanlı bir fiyat listesinde gün boyunca binlerce kez \'en düşük\', \'en yüksek\' ve \'ortanca fiyat\' soruluyor. En verimli hazırlık hangisidir?', 'Listeyi bir kez sıralayıp her soruyu ilgili konuma bakarak yanıtlamak', ['Her soru geldiğinde listeyi baştan sona tarayıp yanıtı hesaplamak', 'Her soru geldiğinde listeyi yeniden sıralayıp ilgili konuma bakmak', 'Listeyi rastgele karıştırıp yalnız ilk 100 elemana bakarak tahmini bir yanıt vermek'], 'Sıralı listede en düşük ilk, en yüksek son, ortanca ise ortadaki elemandır; her soru O(1) sürede yanıtlanır. Tek seferlik n log n maliyet binlerce soruya bölününce önemsizleşir.'),
  ('Bir postane, mektupları önce posta kodunun ilk rakamına göre 10 kutuya ayırıyor, sonra her kutuyu ikinci rakama göre yeniden 10 kutuya ayırıyor ve bu böyle sürüyor. Bu yöntem hangi sıralama yaklaşımının günlük örneğidir?', 'MSD taban sıralaması', ['LSD taban sıralaması', 'Seçmeli sıralama', 'Kabarcık sıralaması'], 'En anlamlı basamaktan başlanıp her grup bir sonraki basamağa göre alt gruplara bölünür; bu, en anlamlı basamaktan başlayan (MSD) taban sıralamasıdır.'),
  ('0\'dan 7\'ye kadar sayılardan biri eksik olan sıralı 0, 1, 2, 3, 5, 6, 7 dizisinde eksik sayı ikili aramayla bulunuyor. Aramanın dayandığı özellik hangisidir?', 'Eksik sayının solunda a[i] = i, sağında a[i] = i + 1 olması', ['Eksik sayının her zaman dizinin tam ortasında bulunması', 'Dizideki bütün sayıların tek sayı olması', 'Dizinin toplamının her zaman çift sayı olması ve yarıya bölünebilmesi'], 'Eksikten önceki her eleman kendi indisine eşittir, sonrakiler ise bir fazladır. a[orta] = orta ise eksik sağdadır, değilse soldadır; bu örnekte 4 bulunur.'),
  ('Bir sıralı dizinin artan mı azalan mı olduğu bilinmiyor. Aynı ikili arama kodunu iki durumda da kullanmak için ne yapılabilir?', 'İlk ve son eleman karşılaştırılarak yön belirlenir ve karşılaştırma buna göre ters çevrilir', ['Dizi önce her durumda artan sıraya göre yeniden sıralanır', 'Arama iki kez yapılır ve iki sonuçtan küçük olanı seçilir', 'Dizinin ortasındaki eleman çıkarılıp arama iki yarıda ayrı ayrı yapılır ve sonuçlar karşılaştırılır'], 'a[0] < a[n − 1] ise dizi artandır; değilse azalandır. Yön bilindikten sonra sağa ya da sola gitme kararları buna göre verilir; bu yaklaşıma yönden bağımsız ikili arama denir.'),
  ('Her elemanın sıralı dizideki doğru konumundan en fazla bir konum uzakta olabildiği \'neredeyse sıralı\' bir dizide değer ikili aramayla nasıl aranır?', 'Her adımda orta, orta − 1 ve orta + 1 konumlarına birlikte bakılır', ['Orta eleman yerine her zaman ilk eleman denetlenir', 'Arama aralığı her adımda ikiye değil dörde bölünür ve dört ayrı parça ayrı ayrı denetlenir', 'İkili arama uygulanamaz; dizi önce tamamen sıralanmalıdır'], 'Aranan değer beklenen yerin bir yanına kaymış olabilir; üç komşu birlikte denetlenir. Bulunamazsa a[orta] ile karşılaştırılıp aralık iki konum fazla daraltılır.'),
  ('m satırlı bir matriste yalnız her satır kendi içinde sıralıdır, sütunlar sıralı değildir. Bir değeri aramanın verimli yolu hangisidir?', 'Her satırda ayrı ikili arama yapmak', ['Sağ üst köşeden merdiven araması yapmak', 'Matrisi tek dizi gibi düşünüp bir ikili arama yapmak', 'Yalnız ilk sütunda ikili arama yapıp bulunan satıra bakmak ve orada durmak'], 'Sütunlar sıralı olmadığından merdiven araması ve satırlar arası sıra varsayan yöntemler hatalıdır. Satırlar bağımsız sıralı olduğundan her birinde ikili arama yapılır.'),
  ('100 katlı bir binada elinizde 1 yumurta var ve yumurtanın kırılmadan bırakılabileceği en yüksek katı kesin bulmanız gerekiyor. Kırılan yumurta bir daha kullanılamıyorsa en kötü durumda kaç atış gerekir?', '100', ['7', '14', '50'], 'Tek yumurtayla ikili arama yapılamaz; yumurta ortada kırılırsa alt katlar hakkında bilgi kalmaz. 1. kattan başlayıp yukarı doğru tek tek denemek zorunludur.'),
  ('100 katlı bir binada, kırılan yumurtanın bir daha kullanılamadığı koşulda 2 yumurtayla kırılmadan bırakılabilecek en yüksek kat kesin olarak bulunacak. En iyi strateji en kötü durumda kaç atış gerektirir?', '14', ['10', '7', '50'], 'İlk yumurta 14, 27, 39, … katlarından atılır (aralık her seferinde bir azalır); kırılınca ikinci yumurtayla aradaki katlar tek tek denenir. k(k + 1)/2 ≥ 100 koşulunu sağlayan en küçük k 14\'tür.'),
  ('Sıralı harf listesi [c, f, j] içinde \'j\'den büyük en küçük harf aranıyor; uygun harf yoksa listenin başına dönülmesi isteniyor. Sonuç hangisidir?', 'c', ['j', 'f', 'Sonuç yok'], 'j\'den kesin büyük harf yoktur; üst sınır araması listenin sonunu gösterir. Döngüsel kural gereği indis mod 3 alınır ve başa dönülerek c bulunur.'),
  ('Bir sıralama algoritmasının 5, 1, 4, 2, 8 dizisindeki ara durumları şöyledir: 1, 5, 4, 2, 8 → 1, 4, 5, 2, 8 → 1, 2, 4, 5, 8. Bu izler en çok hangi algoritmaya uyar?', 'Eklemeli sıralama', ['Seçmeli sıralama', 'Kabarcık sıralaması', 'Birleştirmeli sıralama'], 'Her adımda baştaki bölüm bir eleman büyüyerek kendi içinde sıralı kalıyor; yeni eleman (4, sonra 2) bu bölümde doğru yerine sokuluyor. Bu, eklemeli sıralamanın davranışıdır.'),
  ('Bir algoritmanın 3, 7, 1, 9, 4 dizisindeki ara durumları şöyledir: 1, 7, 3, 9, 4 → 1, 3, 7, 9, 4 → 1, 3, 4, 9, 7 → 1, 3, 4, 7, 9. Hangi algoritma çalışmaktadır?', 'Seçmeli sıralama', ['Eklemeli sıralama', 'Kabarcık sıralaması', 'Hızlı sıralama'], 'Her adımda kalanların en küçüğü bulunup başa takas ediliyor (1 ile 3, 3 ile 7, 4 ile 7, 7 ile 9). Baştaki bölüm, dizinin en küçük elemanlarından oluşuyor.'),
  ('Bir algoritmanın 6, 2, 8, 3, 7, 1, 5, 4 dizisindeki ilk iki ara durumu şöyledir: 2, 6, 3, 8, 1, 7, 4, 5 → 2, 3, 6, 8, 1, 4, 5, 7. Bu izler hangi algoritmaya aittir?', 'Aşağıdan yukarı birleştirmeli sıralama', ['Eklemeli sıralama', 'Shell sıralaması', 'Kabarcık sıralaması'], 'İlk adımda komşu ikililer, ikinci adımda dörtlü gruplar kendi içinde sıralanıyor. Bu, boyu iki katına çıkan grupları birleştiren aşağıdan yukarı birleştirmeli sıralamadır.'),
  ('Bir algoritma ilk adımdan sonra 7, 3, 9, 1, 5 dizisini 3, 1, 5, 7, 9 hâline getiriyor: 5\'ten küçükler solda, büyükler sağda ve 5 aralarında. Bu ilk adım hangi algoritmaya özgüdür?', 'Hızlı sıralamanın bölümleme adımı', ['Kabarcık sıralamasının ilk geçişi', 'Seçmeli sıralamanın ilk takası', 'Birleştirmeli sıralamanın ilk birleştirme adımı'], 'Bir pivotun (5) kesin yerine oturup küçüklerin soluna, büyüklerin sağına toplanması bölümlemenin işaretidir. Sol ve sağ parçalar henüz kendi içinde sıralı değildir.'),
  ('Sıralı bir dizide yanlışlıkla iki eleman yer değiştirmiş: 1, 6, 3, 4, 5, 2, 7. Bu iki eleman tek bir taramayla nasıl bulunur?', 'İlk azalmanın büyük elemanı ile son azalmanın küçük elemanı alınır', ['En büyük ve en küçük eleman yer değiştirilir', 'Ortadaki eleman ile ilk eleman yer değiştirilir', 'Dizi ikili aramayla taranıp eşleşmeyen ilk eleman bulunur'], 'Komşu çiftlerde azalma 6 > 3 ve 5 > 2 noktalarında görülür. İlk azalmanın büyüğü (6) ile son azalmanın küçüğü (2) takas edilince dizi düzelir; yer değiştirenler komşuysa tek azalma görülür.'),
  ('A dizisi sıralı m elemandan sonra n boş yer içeriyor; sıralı n elemanlı B dizisi A\'ya ek bellek kullanmadan birleştirilecek. En kolay ve güvenli yol hangisidir?', 'Birleştirmeye iki dizinin sonundan başlayıp A\'nın sonundan geriye doğru yazmak', ['Birleştirmeye baştan başlayıp A\'nın başından ileriye doğru yazmak', 'B\'yi A\'nın sonundaki boş yerlere kopyalayıp ardından bütün diziye kabarcık sıralaması uygulamak', 'A\'yı B\'nin sonuna kopyalayıp B\'yi büyütmek ve ardından baştan birleştirmek'], 'En büyük elemanlar boş yerlere yazıldığı için A\'nın henüz işlenmemiş elemanlarının üzerine yazılmaz. Baştan yazmak ise okunmamış A elemanlarını ezer.'),
  ('4, 6, 2, 6, 4, 4 dizisi önce sıklığa göre azalan, eşit sıklıkta değere göre artan olarak sıralanıyor. Sonuç nedir?', '4, 4, 4, 6, 6, 2', ['2, 4, 4, 4, 6, 6', '6, 6, 4, 4, 4, 2', '4, 4, 4, 2, 6, 6'], 'Sıklıklar 4 → 3, 6 → 2, 2 → 1\'dir. Anahtar (−sıklık, değer) olarak alındığında önce üç 4, sonra iki 6, en sonda 2 gelir.'),
  ('Bir web sayfası ürünleri fiyata göre sıralıyor; aynı fiyatlı ürünlerin sırası her yenilemede değişiyor ve kullanıcılar şikâyet ediyor. En uygun çözüm hangisidir?', 'Eşitlikte ürün kimliği gibi ikinci bir sabit ölçüt eklemek', ['Fiyatları rastgele küçük miktarlarla değiştirmek', 'Sıralamayı kaldırıp ürünleri ekleme sırasıyla göstermek', 'Aynı fiyatlı ürünlerden yalnız birini gösterip ötekileri gizlemek'], 'Kararsız bir algoritma ya da değişen girdi sırası, eşit anahtarlıları farklı dizebilir. Benzersiz bir ikinci ölçüt sonucu her seferinde belirlenmiş (deterministik) yapar.'),
  ('Python\'da sorted([\'elma\', \'Zeytin\', \'armut\'], key=str.lower) ifadesinin sonucu nedir?', '[\'armut\', \'elma\', \'Zeytin\']', ['[\'Zeytin\', \'armut\', \'elma\']', '[\'Zeytin\', \'elma\', \'armut\']', '[\'elma\', \'Zeytin\', \'armut\']'], 'Karşılaştırma küçük harfe çevrilmiş anahtarlarla yapılır, ama listedeki sözcükler değişmez. Anahtar verilmeseydi büyük harfli \'Zeytin\' başa geçerdi.'),
  ('Python\'da sorted([(2, \'b\'), (1, \'z\'), (2, \'a\')]) ifadesi demetleri nasıl sıralar?', '[(1, \'z\'), (2, \'a\'), (2, \'b\')]', ['[(2, \'a\'), (2, \'b\'), (1, \'z\')]', '[(1, \'z\'), (2, \'b\'), (2, \'a\')]', '[(2, \'a\'), (1, \'z\'), (2, \'b\')]'], 'Demetler sözlük sırasıyla karşılaştırılır: önce ilk öğeler, eşitse ikinci öğeler. 1 en küçük olduğundan başa gelir; ilk öğesi 2 olanlar \'a\' ve \'b\'ye göre dizilir.'),
  ('Python\'da sorted(\'kitap\') çağrısının sonucu nedir?', '[\'a\', \'i\', \'k\', \'p\', \'t\']', ['\'aikpt\'', '[\'k\', \'i\', \'t\', \'a\', \'p\']', '\'tpkia\''], 'sorted her zaman liste döndürür; bir metin verildiğinde karakterlerini sıralı bir liste olarak verir. Metin isteniyorsa \'\'.join(...) ile birleştirilmelidir.'),
  ('Python\'da max([\'ay\', \'kuş\', \'gün\', \'su\'], key=len) çağrısı hangi değeri döndürür?', '\'kuş\'', ['\'gün\'', '\'su\'', '[\'kuş\', \'gün\']'], 'En uzun sözcükler 3 harfli \'kuş\' ve \'gün\'dür. max eşitlik durumunda karşılaştığı ilk en büyük elemanı döndürür; bu yüzden \'kuş\' gelir.'),
  ('Python\'da d = {\'a\': 3, \'b\': 1, \'c\': 2} sözlüğü değerlerine göre sıralanmak isteniyor. sorted(d.items(), key=lambda kv: kv[1]) ifadesinin sonucu nedir?', '[(\'b\', 1), (\'c\', 2), (\'a\', 3)]', ['[\'b\', \'c\', \'a\']', '[(\'a\', 3), (\'b\', 1), (\'c\', 2)]', '[1, 2, 3]'], 'items() (anahtar, değer) çiftlerini verir; anahtar işlevi çiftin ikinci öğesini seçtiği için çiftler değerlere göre dizilir.'),
  ('Python\'da bir öğrenci listesi ada göre azalan, eşit adlarda yaşa göre artan biçimde sıralanacak. Ad metin olduğu için anahtarda eksi işareti kullanılamıyor. Kararlı sıralamayla hangi yol izlenir?', 'Önce yaşa göre artan, sonra ada göre reverse=True ile sıralamak', ['Önce ada göre azalan, sonra yaşa göre artan sıralamak', 'Ad ve yaşı birleştirip tek bir metin olarak bir kez sıralamak', 'Önce yaşa göre azalan, sonra ada göre artan sıralayıp listeyi ters çevirmek ve en sonda bir kez daha sıralamak'], 'Kararlı sıralamada ikincil ölçüte göre önce, birincil ölçüte göre en son sıralanır. reverse=True da kararlılığı korur, bu yüzden eşit adlıların yaş sırası bozulmaz.'),
  ('Unix\'te 10, 9 ve 100 değerlerinin bulunduğu satırlar sort komutuyla seçeneksiz sıralanırsa çıktı ne olur?', '10, 100, 9', ['9, 10, 100', '100, 10, 9', '9, 100, 10'], 'sort varsayılan olarak satırları metin olarak karşılaştırır; \'1\' ile başlayanlar \'9\'dan önce gelir. Sayısal sıralama için sort −n kullanılır ve 9, 10, 100 elde edilir.'),
  ('JavaScript\'te [\'ç\', \'c\', \'d\'].sort() çağrısı [\'c\', \'d\', \'ç\'] verir. Türkçe alfabe sırasını elde etmek için hangi karşılaştırma kullanılmalıdır?', '(a, b) => a.localeCompare(b, \'tr\')', ['(a, b) => a − b', '(a, b) => a.length − b.length', '(a, b) => b.localeCompare(a)'], 'Varsayılan sıralama UTF-16 kod birimlerine göredir ve \'ç\' \'d\'den sonra gelir. localeCompare\'e \'tr\' dil kodu verilince Türkçe kurallarla c, ç, d sırası elde edilir.'),
  ('n elemanlı bir dizide yarıdan fazla kez geçen bir \'çoğunluk elemanı\' bulunduğu biliniyor. Dizi sıralandıktan sonra bu eleman nerede kesinlikle bulunur?', 'Ortadaki (⌊n/2⌋ indisli) konumda', ['Dizinin ilk konumunda', 'Dizinin son konumunda', 'En sık değişen iki komşu elemanın arasında'], 'Yarıdan fazla yer kaplayan bir değer sıralı dizide hangi konumda başlarsa başlasın ortayı mutlaka örter. Bu yöntem n log n sürer; doğrusal yöntemler de vardır.'),
  ('Tek bir işlemcide süreleri 3, 1 ve 2 dakika olan üç iş bekliyor. Ortalama bekleme süresini en aza indirmek için işler süreye göre kısadan uzuna sıralanırsa ortalama bekleme süresi kaç dakika olur?', '4/3', ['5/3', '2', '7/3'], 'Sıra 1, 2, 3 olur; bekleme süreleri 0, 1 ve 1 + 2 = 3 dakikadır. Ortalama (0 + 1 + 3)/3 = 4/3 dakikadır. Kısa işi önce yapmak (SJF) bu ortalamayı en aza indirir.'),
  ('Çocuklara kurabiye dağıtılacak: her çocuğun en az isteği (açlık değeri) ve her kurabiyenin boyu biliniyor; bir çocuğa yalnız isteğini karşılayan tek kurabiye verilebilir. Olabildiğince çok çocuğu doyurmak için hangi yaklaşım kullanılır?', 'İki listeyi de sıralayıp en küçük yeterli kurabiyeyi en az isteyen çocuğa vermek', ['En büyük kurabiyeyi her zaman en az isteyen çocuğa vermek', 'Kurabiyeleri rastgele dağıtıp yetmeyenleri geri almak', 'Yalnız kurabiyeleri sıralayıp çocuklara adlarının alfabetik sırasıyla birer birer dağıtmak'], 'İki işaretçiyle sıralı listeler taranır: kurabiye yetiyorsa iki işaretçi ilerler, yetmiyorsa yalnız kurabiye işaretçisi ilerler. Büyük kurabiyeler daha istekli çocuklara kalır.'),
  ('Bir sözcük listesinin bütün sözcüklerine ortak en uzun öneki bulmak için liste sözlük sırasına konuyor. Bundan sonra yalnız hangi sözcükleri karşılaştırmak yeterlidir?', 'İlk ve son sözcüğü', ['Yalnız en kısa iki sözcüğü', 'Bütün komşu sözcük çiftlerini', 'Ortadaki iki sözcüğü ve listenin en uzun sözcüğünü'], 'Sıralı listede ilk ve son sözcük birbirinden en farklı olanlardır; ikisinin ortak öneki aradaki bütün sözcüklerde de bulunur. Örneğin kalem, kalemci, kalemlik, kalemtıraş için sonuç \'kalem\'dir.'),
  ('Bir kütüphane kitapları hem yazara hem de başlığa göre hızlı aranabilir kılmak istiyor; kitaplar rafta tek bir sırada durabiliyor. Bilgisayar dizinlerindeki karşılığıyla çözüm nedir?', 'Her ölçüte göre ayrı sıralı bir dizin tutmak', ['Kitapları her gün dönüşümlü olarak yazara ve başlığa göre yeniden dizmek', 'Yazar ve başlığı birleştirip tek bir alana göre sıralamak', 'Rafları rastgele düzenleyip her aramada bütün kitaplara bakmak'], 'Veri bir kez saklanır; her arama ölçütü için o ölçüte göre sıralı, kayda işaret eden ayrı bir dizin (eski kart kataloglarındaki yazar ve başlık kartları gibi) tutulur.'),
  ('Rabin–Karp algoritmasında rakamlardan oluşan metinde 3 uzunluklu pencerenin değeri onluk sayı olarak tutuluyor. \'1234\' metninde \'123\' penceresinin değeri 123 iken pencere bir sağa kayınca yeni değer hangi işlemle bulunur?', '(123 − 1·100)·10 + 4', ['123·10 + 4', '(123 + 4)·10 − 1', '123 − 1 + 4'], 'Soldan çıkan rakamın katkısı (1·100) çıkarılır, kalan 10 ile çarpılarak bir basamak kaydırılır ve yeni rakam eklenir: 23·10 + 4 = 234. Böylece her pencere sabit sürede hesaplanır.'),
  ('\'cbaebabacd\' metninde \'abc\' kalıbının bir anagramıyla başlayan konumlar, 3 uzunluklu kayan pencerede harf sayıları güncellenerek aranıyor. Hangi başlangıç konumları (0\'dan) bulunur?', '0 ve 6', ['Yalnız 0', '1 ve 6', '0, 4 ve 6'], 'Pencereler \'cba\' (0) ve \'bac\' (6), \'abc\' ile aynı harfleri içerir. Pencere kaydıkça bir harf çıkıp bir harf girdiği için sayım her adımda sabit sürede güncellenir.'),
  ('Naif dizge aramasının en iyi durumu hangi girdide ortaya çıkar?', 'Kalıbın ilk karakteri metindeki hiçbir karakterle eşleşmediğinde', ['Kalıp metnin tamamıyla aynı olduğunda', 'Metin yalnız aynı harfin tekrarından oluştuğunda', 'Kalıp metnin sonunda bir kez geçtiğinde ve son harf eşleşmediğinde'], 'Her hizalamada ilk karşılaştırma başarısız olur; toplam n − m + 1 karşılaştırmayla arama biter. Kötü durumda ise her hizalamada m karşılaştırma yapılır.'),
  ('Yığın sıralamasının en iyi durumdaki (ör. zaten sıralı girdi) süresi hangi mertebededir?', 'n log n', ['n', 'log n', 'n²'], 'Yığın sıralaması önce yığını kurar, sonra her çıkarmada kökü aşağı süzer; girdinin sıralı olması bu süzmeleri kısaltmaz. Bu yüzden uyarlanabilir değildir.'),
  ('Standart (yukarıdan aşağı) birleştirmeli sıralama zaten sıralı bir diziyle çalıştırılırsa ne olur?', 'Yine n log n mertebesinde iş yapar', ['Tek geçişte doğrusal sürede biter', 'Karesel süreye düşer', 'Hiç karşılaştırma yapmadan sonucu döndürür'], 'Bölme adımları girdinin düzenine bakmaz; birleştirmelerde karşılaştırma sayısı azalsa da (her birleştirmede yaklaşık yarısı) bütün düzeyler yine işlenir. Doğal birleştirme ve Timsort bu durumu doğrusal sürede tanır.'),
  ('Bir sokakta 1, 2, 4, 8 ve 9 numaralı konumlardaki evlerden üçüne kablosuz verici konacak ve vericiler arasındaki en küçük uzaklık olabildiğince büyük olacak. Bu en büyük \'en küçük uzaklık\' ikili aramayla bulunursa kaçtır?', '3', ['2', '4', '7'], 'd = 3 için 1, 4 ve 8 seçilebilir; d = 4 için 1\'den sonra 8 seçilir ve üçüncü verici için yer kalmaz. Yüklem \'d uzaklığıyla 3 verici yerleşir mi?\' büyüdükçe doğrudan yanlışa döner.'),
  ('İki makineden biri 2 dakikada, öteki 3 dakikada bir ürün üretiyor ve ikisi aynı anda çalışmaya başlıyor. 5 ürünün tamamlandığı en erken tam dakika ikili aramayla bulunuyor. Sonuç kaçtır?', '6', ['5', '4', '10'], 't dakikada üretilen ürün sayısı ⌊t/2⌋ + ⌊t/3⌋\'tür ve t ile azalmaz. t = 5 için 2 + 1 = 3, t = 6 için 3 + 2 = 5 ürün çıkar.'),
  ('[0, 100] aralığında ikiye bölme yöntemiyle bir kök aranıyor ve aralık genişliği 0,01\'in altına inince durulacak. En az kaç adım gerekir?', '14', ['10', '100', '7'], '100/2ᵏ < 0,01 için 2ᵏ > 10 000 olmalıdır. 2¹³ = 8192 yetmez, 2¹⁴ = 16 384 yeter; bu yüzden 14 adım gerekir.'),
  ('Sıralı −4, −1, 0, 3, 10 dizisindeki sayıların kareleri sıralı biçimde, iki uçtan başlayan işaretçilerle ve sonuç dizisi sondan doldurularak üretiliyor. Sonuç dizisi nedir?', '0, 1, 9, 16, 100', ['16, 1, 0, 9, 100', '100, 16, 9, 1, 0', '0, 1, 16, 9, 100'], 'Mutlak değeri en büyük eleman ya en soldadır ya en sağda; her adımda büyük karesi alınan uç sonuçların sonuna yazılır. Böylece yeniden sıralamaya gerek kalmadan O(n) sürede sıralı kareler elde edilir.'),
  ('Sıralı A ve B dizilerinden birer eleman alarak toplamı hedefe eşit bir çift aranıyor. İki işaretçi nasıl başlatılır?', 'A\'nın başından ve B\'nin sonundan', ['İkisi de dizilerin başından', 'İkisi de dizilerin sonundan', 'A\'nın ortasından ve B\'nin ortasından başlayıp dışa doğru'], 'Toplam küçükse A\'daki işaretçi ilerletilerek artırılır, büyükse B\'deki işaretçi geri alınarak azaltılır. Böylece tek dizideki iki uçlu yöntem iki diziye uyarlanmış olur.'),
  ('Kabarcık sıralaması 6, 5, 4, 3, 2, 1 dizisine uygulanıyor. İlk iki geçişten sonra dizi nasıl olur?', '4, 3, 2, 1, 5, 6', ['5, 4, 3, 2, 1, 6', '1, 2, 3, 4, 5, 6', '4, 5, 3, 2, 1, 6'], 'İlk geçiş 6\'yı sona taşır: 5, 4, 3, 2, 1, 6. İkinci geçiş 5\'i sondan bir önceki konuma taşır: 4, 3, 2, 1, 5, 6.'),
  ('Yukarıdan aşağı birleştirmeli sıralama 5, 2, 4, 7, 1, 3, 2, 6 dizisinde önce sol yarıyı tamamen sıralıyor. Sol yarının sıralanması bittiği anda (sağ yarıya henüz dokunulmamışken) dizi nasıldır?', '2, 4, 5, 7, 1, 3, 2, 6', ['1, 2, 2, 3, 4, 5, 6, 7', '2, 5, 4, 7, 1, 3, 2, 6', '2, 4, 5, 7, 1, 2, 3, 6'], 'Özyineleme önce sol yarıdaki 5, 2, 4, 7\'yi sıralar ve 2, 4, 5, 7 elde eder. Sağ yarı ancak bundan sonra işlenir.'),
  ('Son elemanı pivot alan hızlı sıralama zaten sıralı 1, 2, 3, 4, 5 dizisini sıralarken bölümlemelerde toplam kaç karşılaştırma yapar?', '10', ['5', '4', '25'], 'Her bölümlemede pivot en büyük elemandır ve bütün ötekiler bir tarafa düşer: 4 + 3 + 2 + 1 = 10 karşılaştırma. Bu, n(n − 1)/2 ile verilen en kötü durumdur.'),
  ('Eklemeli sıralamada i. adımdan sonra baştaki i + 1 eleman kendi içinde sıralıdır. Bu elemanlar dizinin son sıralı hâlindeki yerlerinde midir?', 'Hayır; sonradan gelen küçük elemanlar onları sağa kaydırabilir', ['Evet; eklemeli sıralama her adımda bir elemanı kesin yerine koyar', 'Evet; ama yalnız dizi tek sayıda elemansa', 'Hayır; çünkü baştaki bölüm hiçbir zaman sıralı olmaz'], 'Eklemeli sıralamada baştaki bölüm yalnız şimdiye kadar görülen elemanların sıralı hâlidir. Seçmeli sıralamada ise baştaki elemanlar dizinin en küçükleridir ve kesin yerlerindedir.'),
  ('Birleştirme işlevinde iki işaretçi dizilerden biri bitene kadar ilerletiliyor, ancak döngüden sonra öbür dizide kalan elemanlar sonuca kopyalanmıyor. Sonuç ne olur?', 'Bazı elemanlar sonuçtan eksik kalır', ['Sonuç doğru ama kararsız olur', 'Eleman sayısı iki katına çıkar', 'Sonuç ters sırada çıkar ama bütün elemanları içerir'], 'Bir dizi bittiğinde ötekinde kalanlar zaten sıralıdır ve aynen eklenmelidir. Kopyalama unutulursa örneğin 1, 2 ile 3, 4 birleştirilirken 3 ve 4 kaybolur.'),
  ('Lomuto bölümlemesiyle yazılmış hızlı sıralamada pivotun son konumu p iken özyinelemeli çağrılar yanlışlıkla [alt, p] ve [p + 1, üst] aralıklarıyla yapılıyor. Hangi sorun ortaya çıkabilir?', 'Pivot en büyükse aralık küçülmez ve sonsuz özyineleme oluşur', ['Sağ yarı hiç sıralanmaz', 'Dizi azalan sıraya dizilir', 'Pivot iki kez kopyalanır ve dizide fazladan bir eleman oluşur'], 'Lomuto\'da pivot kesin yerindedir ve özyinelemeye katılmamalıdır. Pivot dizinin en büyüğü ise p = üst olur; [alt, p] aynı aralık olduğundan çağrı kendini sonsuza dek tekrarlar.'),
  ('Seçmeli sıralamada i. adımda en küçük eleman aranırken iç döngü yanlışlıkla i + 1 yerine 0\'dan başlatılıyor. Ne olur?', 'Zaten yerleşmiş küçük elemanlar yeniden seçilip sıra bozulur', ['Algoritma doğru çalışır, yalnız biraz yavaşlar', 'Algoritma kararlı hâle gelir', 'Dizi tek adımda sıralanır ve kalan adımlar boşa çalışır'], 'Aranan bölge baştaki sıralı kısmı da içerdiğinden \'en küçük\' her seferinde dizinin en küçüğü olur ve i. konumdaki elemanla takas edilir; önceki yerleşimler bozulur.'),
  ('Eklemeli sıralama kodunda büyük elemanlar sağa kaydırıldıktan sonra yerleştirilecek değer (anahtar) boşalan konuma yazılmıyor. Sonuç ne olur?', 'Anahtar kaybolur ve bir eleman iki kez görünür', ['Dizi doğru sıralanır ama işlem uzar', 'Dizi ters sıralanır', 'Anahtar dizinin sonuna eklenir ve dizi bir eleman uzar'], 'Kaydırma, soldaki büyük elemanı bir sağa kopyalar; anahtar yazılmazsa son kopyalanan eleman iki konumda birden kalır ve anahtarın değeri diziden silinmiş olur.'),
  ('Sayma sıralamasının yerleştirme döngüsünde, bir eleman çıktıya yazıldıktan sonra o değerin birikimli sayacı azaltılmıyor. Ne olur?', 'Aynı değerli elemanlar hep aynı konuma yazılıp birbirini ezer', ['Algoritma kararlı olmaktan çıkar ama sonuç doğru olur', 'Çıktı dizisi ters sırada oluşur', 'Sayaç dizisi negatif değerler alır ve program hemen durur'], 'Sayaç, o değerin bir sonraki elemanı için yeri gösterir; azaltılmazsa eşit değerler aynı göze yazılır ve diğer gözler boş kalır.'),
  ('Kova sıralamasında veriler düzgün dağılmıyor, örneğin gelirler çoğunlukla düşük değerlerde yoğunlaşıyor. Kovaların sınırları nasıl seçilirse algoritma yine dengeli çalışır?', 'Bir örnekten hesaplanan yüzdeliklere göre', ['Bütün kovalar eşit genişlikte tutulursa', 'Yalnız iki kova kullanılırsa', 'Kova sınırları alfabetik olarak belirlenirse ve en son kova en geniş tutulursa'], 'Eşit genişlikli kovalarda yoğun bölgedeki kova taşar. Örnek verinin yüzdelikleri sınır alınınca her kovaya yaklaşık eşit sayıda eleman düşer.'),
  ('Üç farklı sayının ortancasını (ortadaki değerini) bulmak için en kötü durumda kaç karşılaştırma yeterlidir?', '3', ['2', '6', '1'], 'Önce a ile b karşılaştırılır; sonra c ile bunlardan biri karşılaştırılır. Kimi durumda iki karşılaştırma yeter, kimi durumda üçüncüsü gerekir. Hiçbir yöntem her durumda 2 ile yetinemez.'),
  ('Eklemeli sıralama dizi yerine bağlı listeye uygulanınca ne değişir?', 'Kaydırma gerekmez, ama yerleştirme noktası yine baştan taranarak bulunur', ['Algoritma n log n süreye iner', 'Algoritma kararsız hâle gelir', 'Yerleştirme noktası ikili aramayla bulunabilir hâle gelir'], 'Bağlı listede eleman araya bağlantıları değiştirerek sabit sürede eklenir. Ancak ikili arama yapılamadığı için yerini bulmak doğrusal kalır ve toplam süre yine karesel olur.'),
  ('Zaten sıralı büyük bir listenin sonuna sırasız birkaç yeni eleman ekleniyor ve liste yeniden sıralanacak. Timsort bu durumda neden çok hızlıdır?', 'Uzun sıralı koşuyu tanır; yalnız kısa yeni kısmı sıralayıp birleştirir', ['Listeyi baştan karıştırıp sonra sıraladığı için', 'Yeni elemanları atıp eski listeyi döndürdüğü için', 'Her elemanı ikili aramayla tek tek yeniden sıraladığı için'], 'Timsort girdideki sıralı koşuları bulur; büyük koşu olduğu gibi kalır, sondaki kısa kısım sıralanır ve iki koşu tek birleştirmeyle (dörtnala modu da yardımcı olur) birleşir.'),
  ('NumPy\'deki argsort gibi \'dolaylı sıralama\' işlevleri [30, 10, 20] dizisi için ne döndürür?', '[1, 2, 0]', ['[10, 20, 30]', '[2, 0, 1]', '[0, 1, 2]'], 'argsort, elemanları değil, sıralı düzende hangi indisin hangi sırada geleceğini verir: en küçük (10) 1. indiste, sonra 20 (2. indis), sonra 30 (0. indis).'),
  ('Her biri birkaç kilobaytlık büyük kayıtlar tek bir sayısal alana göre sıralanacak. Kayıtları yerinde taşımak yerine indis ya da işaretçi dizisini sıralamanın kazancı nedir?', 'Her takasta yalnız küçük indisler taşınır, büyük kayıtlar kopyalanmaz', ['Karşılaştırma sayısı sıfıra iner', 'Sıralama her durumda doğrusal sürede biter, çünkü indisler küçük tam sayılardır', 'Kayıtlar diskten silinir ve yer kazanılır'], 'Kayıt başına binlerce baytı defalarca kopyalamak pahalıdır. İndis dizisi sıralanır; kayıtlara gerektiğinde bu sırayla erişilir ya da en sonda bir kez yerlerine taşınır.'),
  ('Diziyi ikiye değil üçe bölen ve üç sıralı parçayı birleştiren \'3 yollu birleştirmeli sıralama\' 27 elemanlı bir diziyi tek elemanlı parçalara kaç bölme düzeyinde ayırır?', '3', ['9', '5', '27'], 'Her düzeyde parça boyu üçte birine iner: 27 → 9 → 3 → 1. Bu yüzden 3 düzey yeterlidir; bunun karşılığında her birleştirmede üç baş karşılaştırılır.'),
  ('Yığın sıralaması hangi basit sıralama algoritmasının, \'kalanların en büyüğünü bulma\' adımını hızlandırılmış hâli olarak görülebilir?', 'Seçmeli sıralamanın', ['Eklemeli sıralamanın', 'Kabarcık sıralamasının', 'Sayma sıralamasının'], 'Seçmeli sıralama en büyüğü (ya da en küçüğü) her seferinde doğrusal taramayla bulur; yığın sıralaması aynı seçimi yığın yapısıyla log n sürede yapar.'),
  ('Hızlı sıralama ile birleştirmeli sıralama ikisi de böl ve yönet kullanır. Asıl işin yapıldığı an bakımından aralarındaki fark nedir?', 'Hızlı sıralama asıl işi bölerken, birleştirmeli sıralama birleştirirken yapar', ['Hızlı sıralama asıl işi birleştirirken, birleştirmeli sıralama bölerken yapar', 'İkisi de asıl işi yalnız en derin özyineleme düzeyinde, tek elemanlı parçalarda yapar', 'Hızlı sıralama hiç bölme yapmaz, yalnız birleştirme yapar'], 'Hızlı sıralamada bölümleme sonrası parçaları yan yana koymak yeterlidir. Birleştirmeli sıralamada bölme ortadan kesmektir; sıralamanın yükü birleştirme adımındadır.'),
  ('Hızlı sıralamayı kararlı yapmanın bir yolu bölümlemeyi yerinde değil, ek dizilerle yapmaktır. Bu yöntemde elemanlar nasıl dağıtılır?', 'Küçük, eşit ve büyükler özgün sıraları korunarak ayrı listelere eklenir', ['Elemanlar rastgele iki listeye dağıtılır', 'Pivottan küçükler ters sırayla, büyükler düz sırayla yeni bir diziye yazılır ve eşitler ortaya konur', 'Eşit elemanlar listeden atılır ve sonuna eklenmez'], 'Dizi soldan sağa okunup her eleman ilgili listenin sonuna eklendiğinden eşit anahtarlıların sırası değişmez. Bedeli O(n) ek bellektir.'),
  ('Dizgeleri sıralamak için geliştirilen \'üç yollu taban hızlı sıralaması\' (Bentley–Sedgewick) her adımda neye göre bölümleme yapar?', 'Pivot dizgenin o anki konumdaki karakterine göre küçük, eşit ve büyük', ['Dizgelerin uzunluğuna göre kısa ve uzun', 'Dizgelerin son karakterine göre ikiye', 'Dizgelerin bütününe göre, tek tek karakterlerine hiç bakmadan diziyi iki eşit parçaya böler'], 'Eşit karakterli grup bir sonraki karakter konumuyla özyinelemeli işlenir; küçük ve büyük gruplar aynı konumda kalır. Ortak önekli çok sayıda dizgede tekrar karşılaştırmayı azaltır.'),
  ('\'Amerikan bayrağı sıralaması\' (American flag sort) hangi algoritmanın yerinde çalışan türüdür?', 'MSD taban sıralamasının', ['Kabarcık sıralamasının', 'Yığın sıralamasının', 'Kokteyl sıralamasının'], 'Her basamak için önce kova boyları sayılır, sonra elemanlar ek dizi kullanılmadan takaslarla kendi kovalarına yerleştirilir; ardından her kova bir sonraki basamakla işlenir.'),
  ('Sıralı A = [1, 5, 9] ve B = [2, 3, 7, 8] dizilerinin birleşiminde 4. en küçük eleman, iki diziyi birleştirmeden bulunmak isteniyor. Sonuç kaçtır?', '5', ['3', '7', '4'], 'Birleşik sıra 1, 2, 3, 5, 7, 8, 9\'dur ve dördüncüsü 5\'tir. İkili aramaya dayalı yöntemler bu değeri her adımda dizilerden birinin bir kısmını eleyerek O(log k) sürede bulur.'),
  ('Türkçe alfabe sırasına göre \'inek\', \'ılık\' ve \'iğne\' sözcükleri sıralanırsa hangi dizilim elde edilir?', 'ılık, iğne, inek', ['iğne, inek, ılık', 'inek, iğne, ılık', 'iğne, ılık, inek'], 'Türk alfabesinde ı, i\'den önce gelir; bu yüzden \'ılık\' başa geçer. \'iğne\' ile \'inek\' ikinci harfte ayrılır ve ğ, n\'den önce geldiği için \'iğne\' önce gelir.'),
  ('Kullanıcı arama kutusuna \'sisli\' yazdığında \'Şişli\' sonucunun da gelmesi isteniyor. Bunun için arama öncesinde hem sorguya hem kayıtlara ne uygulanır?', 'Harflerin şapka, nokta ve çengel gibi işaretleri kaldırılıp küçük harfe çevrilir', ['Sözcükler ters çevrilir', 'Bütün sesli harfler silinir', 'Sözcükler harf sayılarına göre sıralanır ve yalnız uzunlukları eşit olan kayıtlar sonuç olarak gösterilir'], 'İşaretlerden bağımsız (aksan duyarsız) arama için ş → s, ç → c, ğ → g gibi dönüşümler yapılır ve harf büyüklüğü eşitlenir; karşılaştırma bu \'sadeleştirilmiş\' biçimler üzerinde yapılır.'),
  ('Yalnız 8 elemanlı sıralı bir dizide arama yapan, saniyede milyonlarca kez çağrılan bir işlevde doğrusal aramanın ikili aramadan hızlı çıkabilmesinin nedeni nedir?', 'Çok küçük dizilerde basit ardışık erişim ve öngörülebilir dallanma ek yükü azaltır', ['Doğrusal arama küçük dizilerde her zaman daha az karşılaştırma yapmayı garanti ettiği için daha hızlıdır', 'İkili arama 8 elemanlı dizilerde yanlış sonuç verir', 'Doğrusal arama sıralı dizilerde her zaman ikili aramadan hızlıdır'], '8 eleman için ikili arama 3 karşılaştırma, doğrusal arama ortalama 4 karşılaştırma yapar; fark küçüktür. Doğrusal aramanın belleğe ardışık erişimi ve işlemcinin tahmin edebildiği dallanmaları pratikte bunu telafi edebilir.'),
  ('Bir araştırmacının makalelerinin atıf sayıları 6, 5, 3, 1, 0\'dır. h-indeksi, en az h atıf almış en az h makale bulunan en büyük h\'dir. Atıflar büyükten küçüğe sıralanıp hesaplanırsa h kaçtır?', '3', ['2', '5', '6'], 'Sıralı listede i. makalenin atıfı i\'den küçük olmadığı sürece h artar: 6 ≥ 1, 5 ≥ 2, 3 ≥ 3 ama 1 < 4. Bu yüzden h = 3\'tür.'),
  ('Dört kişilik bir grup ikili takımlara ayrılacak ve kişilerin süreleri 1, 4, 3, 2 dakika. Takımların toplam sürelerinin en büyüğünü en küçük yapmak için sıralama sonrası hangi eşleştirme yapılır?', 'En küçükle en büyük, sonra kalan en küçükle kalan en büyük', ['En küçük iki kişi bir takımda, en büyük iki kişi öbür takımda olacak biçimde', 'Komşu sıradakiler birlikte', 'Rastgele eşleştirme'], 'Sıralı 1, 2, 3, 4\'te (1, 4) ve (2, 3) eşleşir; en büyük toplam 5 olur. Komşu eşleştirmede (3, 4) = 7 çıkar. Uçları eşlemek yükü dengeler.'),
  ('Bir diskte birbirinin aynısı olan dosyalar aranıyor. Bütün dosyaların içeriğini karşılaştırmadan önce dosyaları boyutlarına göre sıralamanın yararı nedir?', 'Yalnız aynı boyuttaki dosyalar aday kalır, ötekiler hiç okunmaz', ['Aynı boyuttaki dosyalar kesinlikle aynıdır', 'Sıralama dosyaların içeriğini de sıralar', 'Büyük dosyalar küçüklere dönüştürülür ve karşılaştırma kolaylaşır'], 'Farklı boyuttaki iki dosya aynı olamaz. Boyuta göre sıralayınca eşit boyutlular yan yana gelir; yalnız bu grupların içeriği (ya da özet değeri) karşılaştırılır.'),
  ('Bir kişinin dolu olduğu saatler [9.00–10.00], [9.30–11.00], [13.00–14.00]. Aralıklar sıralanıp birleştirildikten sonra 9.00–17.00 arasındaki ilk boş zaman dilimi hangisidir?', '11.00–13.00', ['10.00–13.00', '10.00–11.00', '14.00–17.00'], 'Sıralı aralıklar birleşince [9.00–11.00] ve [13.00–14.00] kalır. Birleşik aralıklar arasındaki ilk boşluk 11.00–13.00\'tür.'),
  ('Çift sayıları öne, tekleri arkaya almak isteyen bir programcı [3, 8, 5, 2, 6] listesini, anahtar olarak x % 2 değerini veren bir işlevle kararlı biçimde diziyor. Sonuç listesi nedir?', '[8, 2, 6, 3, 5]', ['[2, 6, 8, 3, 5]', '[3, 5, 8, 2, 6]', '[2, 3, 5, 6, 8]'], 'Anahtar çift sayılar için 0, tekler için 1\'dir; çiftler öne geçer. Sıralama kararlı olduğundan her grup kendi özgün sırasını korur: 8, 2, 6 ve 3, 5.'),
  ('Bir öğrenci {\'b\': 1, \'a\': 2} sözlüğünü değerlerine göre dizmeyi umarak doğrudan sorted(d) yazıyor. Aldığı sonuç nedir?', '[\'a\', \'b\']', ['[1, 2]', '[(\'a\', 2), (\'b\', 1)]', '{\'a\': 2, \'b\': 1}'], 'Bir sözlük üzerinde dolaşıldığında anahtarları gelir; sorted bunları sıralı bir liste olarak döndürür. Değerleri ya da çiftleri sıralamak için values() ya da items() kullanılmalıdır.'),
  ('Java\'da kişiler önce soyada, eşit soyadlarda ada göre sıralanacak. Comparator ile bu nasıl yazılır?', 'Comparator.comparing(Kisi::getSoyad).thenComparing(Kisi::getAd)', ['Comparator.comparing(Kisi::getAd).thenComparing(Kisi::getSoyad)', 'Comparator.comparing(Kisi::getSoyad).reversed().thenComparing(Kisi::getAd).reversed()', 'Comparator.naturalOrder()'], 'comparing birincil ölçütü, thenComparing ise birincil eşit olduğunda kullanılacak ikincil ölçütü belirtir. Sıra ters yazılırsa önce ada göre sıralanır.'),
  ('Yalnız küçük İngilizce harflerden (26 harf) oluşan 6 harfli bir parolanın arama uzayı yaklaşık kaç olasılıktan oluşur?', 'Yaklaşık 309 milyon', ['156', 'Yaklaşık 2,3 milyon', 'Yaklaşık 26 milyar'], '26⁶ = 308 915 776 olasılık vardır. Arama uzayı uzunlukla üstel büyür; bir harf eklemek uzayı 26 katına çıkarır.'),
  ('Pozitif sayılardan toplamı hedefe eşit bir alt küme geri izlemeyle aranıyor. Sayılar önce küçükten büyüğe sıralanırsa hangi ek budama yapılabilir?', 'Bir sayı eklenince toplam hedefi aşıyorsa, o sayıdan sonrakiler hiç denenmez', ['En büyük sayı her zaman çözüme dahil edilir', 'Sıralamadan sonra yalnız listenin ilk yarısındaki sayılar denenir, ikinci yarı tamamen atılır', 'Toplam hedefe eşit olunca arama baştan başlatılır'], 'Sıralı listede sonraki sayılar daha büyük olduğundan, bir sayı hedefi aşıyorsa ondan sonrakiler de aşar; döngü o noktada kesilebilir.'),
  ('İki hamlelik bir oyun ağacında kökte MAX oyuncu, altında iki MIN düğümü var. Birinci MIN düğümünün yaprakları 3 ve 5, ikincisininki 2 ve 9. Minimaks algoritmasına göre kökün değeri kaçtır?', '3', ['2', '5', '9'], 'MIN düğümleri en küçüğü seçer: min(3, 5) = 3 ve min(2, 9) = 2. MAX kök bunların büyüğünü seçer: 3.'),
  ('Kökü MAX olan iki düzeyli bir oyun ağacında iki MIN düğümü var: birincinin yaprakları 3 ve 5, ikincinin yaprakları 2 ve 9. Alfa-beta budaması soldan sağa çalışırsa hangi yaprak hiç değerlendirilmez?', '9', ['5', '2', '3'], 'İlk MIN düğümünden kök en az 3\'ü garantiler. İkinci MIN düğümünde 2 görülünce bu düğümün değeri en fazla 2 olacağından 9\'a bakmaya gerek kalmaz.'),
  ('Bir arama yönteminin her düzeyde en iyi k adayı tutup gerisini atması (\'ışın araması\', beam search) kaba kuvvete göre neyi feda eder?', 'En iyi çözümü bulma garantisini', ['Hiçbir şeyi; her zaman en iyi çözümü bulur', 'Aramanın sonlanmasını; hiç durmaz', 'Sonucun geçerli bir çözüm olmasını; çıktı her zaman geçersizdir'], 'Elenen adaylardan biri ileride en iyi çözüme gidebilirdi. Işın araması bellek ve süreyi k ile sınırlar ama en iyiyi garanti etmez.'),
  ('Python 3\'te sorted([3, None, 1]) çağrısı ne sonuç verir?', 'TypeError hatası verir', ['[None, 1, 3]', '[1, 3, None]', '[1, 3]'], 'Python 3, None ile tam sayıyı \'<\' ile karşılaştırmaya izin vermez. None değerleri önce ayıklanmalı ya da anahtar işleviyle (ör. x is None, x) uygun bir yere konmalıdır.'),
  ('Python\'da a = [7, 3, 9, 3] iken min(range(len(a)), key=lambda i: a[i]) ifadesi neyi döndürür?', '1', ['3', '0', '[1, 3]'], 'İndisler 0–3 arasında dolaşılır ve her indis a[i] değerine göre karşılaştırılır. En küçük değer 3\'tür; min eşitlikte ilk bulduğu indisi (1) döndürür.'),
  ('IPv4 adresleri (\'10.0.0.2\', \'10.0.0.10\' gibi) metin olarak sıralanınca yanlış sıra çıkıyor. En sağlam çözüm hangisidir?', 'Her adresi dört baytı birleştiren 32 bitlik bir sayıya çevirip ona göre sıralamak', ['Adresleri uzunluklarına göre sıralamak', 'Adreslerdeki noktaları silip geriye kalan rakam dizisini metin olarak sıralamak ve sonucu kullanmak', 'Adresleri sondan başa doğru karakter karakter karşılaştırmak'], 'Her bölüm 0–255 arasında bir bayttır; a·2²⁴ + b·2¹⁶ + c·2⁸ + d sayısı adreslerin doğal sırasını verir. Noktaları silmek \'10.0.0.2\' ile \'100.0.0.2\' gibi adresleri karıştırır.'),
  ('(A, 2), (B, 1), (C, 2), (D, 1) kayıtları sayıya göre sıralanmış ve çıktı (D, 1), (B, 1), (A, 2), (C, 2) olmuş. Kullanılan algoritma hakkında ne söylenebilir?', 'Bu çalıştırmada kararlı davranmamıştır', ['Kesinlikle kararlıdır', 'Sıralamayı yanlış yapmıştır', 'Sayıları değil harfleri anahtar almıştır'], 'Girdide B, D\'den önce gelir ve ikisinin anahtarı 1\'dir; çıktıda D öne geçmiştir. Eşit anahtarlıların sırası bozulduğu için algoritma kararlı değildir.'),
  ('1\'den 15\'e kadar sıralı 15 elemanlı bir dizide ikili arama (orta = ⌊(alt + üst)/2⌋) yapılıyor. Dizideki elemanlardan kaç tanesi tam olarak 4 karşılaştırmayla bulunur?', '8', ['4', '1', '15'], 'Arama ağacında 1. düzeyde 1, 2. düzeyde 2, 3. düzeyde 4, 4. düzeyde 8 eleman bulunur. Yani elemanların yarısından fazlası en kötü durumdaki karşılaştırma sayısıyla bulunur.'),
  ('3, 1, 2, 5, 4 dizisinin sıralı hâle gelmesi için en az kaç eleman diziden çıkarılmalıdır?', '2', ['1', '3', '4'], 'Kalanların artan olması gerekir; en uzun artan alt dizi (ör. 1, 2, 4 ya da 1, 2, 5) 3 elemanlıdır. Çıkarılması gereken en az eleman sayısı 5 − 3 = 2\'dir.'),
  ('Python\'da \'aaaa\'.count(\'aa\') ifadesi hangi değeri döndürür?', '2', ['3', '4', '1'], 'str.count örtüşmeyen eşleşmeleri sayar: 0. konumdaki eşleşmeden sonra arama 2. konumdan sürer ve ikinci eşleşme bulunur. Örtüşenler de sayılsaydı sonuç 3 olurdu.'),
  ('Python\'da d = {\'elma\': 3, \'armut\': 7, \'kiraz\': 5} iken max(d, key=d.get) ifadesi ne döndürür?', 'armut anahtarı', ['7', 'kiraz anahtarı', '(\'armut\', 7) çifti'], 'Sözlük üzerinde dolaşmak anahtarları verir; key=d.get her anahtarı değeriyle karşılaştırır. En büyük değere (7) sahip anahtar \'armut\' döner.'),
  ('Bir hesap tablosu programında DÜŞEYARA (VLOOKUP) işlevi \'yaklaşık eşleşme\' kipinde kullanılıyor. Bu kipin doğru çalışması için arama sütunu hakkında ne gerekir?', 'Sütun artan sırada sıralı olmalıdır', ['Sütunda hiç sayı bulunmamalıdır', 'Sütun azalan sırada sıralı olmalıdır', 'Sütundaki bütün değerler birbirine eşit olmalıdır'], 'Yaklaşık eşleşme, aranan değeri aşmayan en büyük değeri ikili aramaya benzer bir yöntemle bulur; sütun sıralı değilse yanlış satır döndürülebilir.'),
  ('Sıralı 1, 2, 3, 4, 5 dizisinde toplamı 6\'dan küçük olan eleman çiftlerinin sayısı iki işaretçiyle bulunuyor: toplam küçükse r − l kadar çift sayılıp sol işaretçi ilerletiliyor. Sonuç kaçtır?', '4', ['6', '3', '10'], 'a[l] + a[r] < 6 ise a[l] ile l ve r arasındaki her eleman da uygun çift oluşturur. Çiftler (1, 2), (1, 3), (1, 4) ve (2, 3)\'tür.'),
  ('1, 3, 4, 9, 10, 11 sıralı ölçümlerinde en büyüğü ile en küçüğü arasındaki fark en fazla 2 olan en kalabalık grup kayan pencereyle aranıyor. Bu grup kaç ölçüm içerir?', '3', ['2', '4', '6'], 'Sağ uç ilerlerken fark 2\'yi aşınca sol uç ilerletilir. 9, 10, 11 penceresinde fark 2\'dir ve 3 eleman vardır; daha büyük uygun pencere yoktur.'),
  ('Timsort girdide r tane doğal koşu bulursa birleştirme aşamasının süresi yaklaşık hangi mertebededir?', 'n log r', ['n log n, r\'den bağımsız', 'n · r', 'r²'], 'Birleştirmeler koşuların sayısıyla ilgili log r düzeyden oluşur ve her düzey n iş yapar. r = 1 ise süre doğrusal, r ≈ n ise n log n olur.'),
  ('İnterpolasyon araması, ikili aramanın aksine neden ad gibi metin anahtarlarına doğrudan uygulanamaz?', 'Tahmin formülü anahtarlar arasında aritmetik fark ve oran hesaplamayı gerektirir', ['Metinler sıralanamadığı için', 'Metin anahtarları her zaman birbirine eşit kabul edildiği için hiçbir tahmin yapılamaz', 'İnterpolasyon araması yalnız tek basamaklı sayılarla çalıştığı için'], 'İkili arama yalnız \'küçük mü, büyük mü\' sorusuna ihtiyaç duyar. İnterpolasyon ise (x − a[alt])/(a[üst] − a[alt]) gibi bir oran ister; metin için önce sayısal bir karşılık tanımlanmalıdır.'),
  ('Bir sıralama algoritması, hangi yöntemi kullanırsa kullansın, en az n mertebesinde işlem yapmak zorundadır. Bunun nedeni nedir?', 'Her elemanın en az bir kez okunması gerekir', ['Her elemanın en az bir kez takas edilmesi gerekir', 'Her elemanın diğer bütün elemanlarla karşılaştırılması gerekir', 'Her eleman için ayrı bir sayaç açılması gerekir'], 'Okunmayan bir eleman nereye konacağı bilinemez; bu yüzden doğrusal süre her sıralama için kaçınılmaz bir alt sınırdır. Sayma ve taban sıralaması uygun koşullarda bu sınıra yaklaşır.'),
  ('Bir ikili arama işlevini sınarken aşağıdaki durumlardan hangisinin denenmesi özellikle önemlidir?', 'Aranan değerin dizideki bütün elemanlardan küçük ya da büyük olması', ['Dizinin rastgele karıştırılmış olması', 'Aranan değerin metin olarak verilmesi', 'Dizinin hep aynı uzunlukta tutulması ve yalnız ortadaki değerin aranması'], 'Sınır hataları en çok aralığın uçlarında ortaya çıkar: ilk eleman, son eleman, bütün elemanlardan küçük ve büyük değerler. Karışık dizi ise ikili aramanın ön koşulunu bozar.'),
  ('Tarak sıralaması 8, 4, 1, 7, 3 dizisinde boşluk 3 ile bir geçiş yapıyor (i ile i + 3 konumları karşılaştırılıp gerekirse takas ediliyor). Geçiş sonunda dizi nasıl olur?', '7, 3, 1, 8, 4', ['7, 4, 1, 8, 3', '3, 4, 1, 7, 8', '1, 3, 4, 7, 8'], '8 ile 7 takas edilir: 7, 4, 1, 8, 3. Ardından 4 ile 3 takas edilir: 7, 3, 1, 8, 4. Uzak takaslar küçük değerleri hızla öne taşır.'),
  ('İplik sıralaması 5, 1, 4, 2, 8, 3 listesinden ilk ipliği çekiyor: ilk elemandan başlayıp son alınandan büyük her elemanı sırayla alıyor. İlk iplik hangisidir?', '5, 8', ['5, 1, 4', '1, 2, 3', '5, 4, 2, 3'], '5 alınır; 1, 4 ve 2 ondan küçük olduğu için atlanır; 8 alınır; 3, 8\'den küçük olduğu için atlanır. Kalan 1, 4, 2, 3 sonraki turlarda işlenir.'),
  ('Python\'da heapq.merge([1, 4, 7], [2, 5], [3, 6]) ne üretir?', 'Sıralı girdileri birleştiren ve 1\'den 7\'ye sırayla değer veren bir yineleyici', ['Üç listeyi uç uca ekleyen sırasız bir liste', 'Her listenin en küçük elemanından oluşan [1, 2, 3] listesi', 'Listeleri tek bir yığına çevirip yalnız bu yığının kökündeki en büyük elemanı (7) veren tek bir değer'], 'heapq.merge, k-yollu birleştirmeyi yığınla ve tembel (lazy) biçimde yapar; bütün girdileri belleğe almadan sıralı akış üretir.'),
  ('JavaScript\'te [\'a10\', \'a2\', \'a1\'] dizisi (a, b) => a.localeCompare(b, undefined, {numeric: true}) ile sıralanırsa sonuç nedir?', '[\'a1\', \'a2\', \'a10\']', ['[\'a1\', \'a10\', \'a2\']', '[\'a10\', \'a2\', \'a1\']', '[\'a2\', \'a1\', \'a10\']'], 'numeric seçeneği metin içindeki rakam dizilerini sayı olarak karşılaştırır; böylece doğal sıralama elde edilir ve 2, 10\'dan önce gelir.'),
  ('Kenar uzunlukları 3, 6, 2, 3 olan çubuklardan üçü seçilerek çevresi en büyük üçgen kurulacak. Uzunluklar büyükten küçüğe sıralanıp üçgen eşitsizliğini sağlayan ilk ardışık üçlü alınırsa çevre kaç olur?', '8', ['12', '9', '15'], 'Sıra 6, 3, 3, 2\'dir. 6 < 3 + 3 sağlanmaz (eşit); sonraki üçlü 3 < 3 + 2 sağlanır ve çevre 3 + 3 + 2 = 8 olur. Sıralı listede ardışık üçlülere bakmak yeterlidir.'),
  ('1, 4, 3, 2 sayıları ikişerli gruplara ayrılacak ve her grubun küçüğünün toplamı en büyük yapılacak. Sayılar sıralanıp yan yana ikililer oluşturulursa elde edilen toplam kaçtır?', '4', ['3', '5', '7'], 'Sıralı dizi 1, 2, 3, 4\'tür; (1, 2) ve (3, 4) gruplarının küçükleri 1 ve 3, toplam 4\'tür. Büyük bir sayıyı küçük bir sayıyla eşlemek o büyük sayıyı boşa harcar.'),
  ('Bir dizinin sıralı hâlinde ardışık iki eleman arasındaki en büyük farkı, diziyi sıralamadan doğrusal sürede bulan yöntem hangi fikre dayanır?', 'n − 1 kovaya dağıtıldığında en büyük farkın bir kovanın içinde değil kovalar arasında çıkacağına', ['Farkın her zaman dizinin en büyük ve en küçük elemanı arasında çıkmasına ve bu iki elemanı bulmanın yeterli olmasına', 'Dizinin ortasındaki iki elemanın en uzak olmasına', 'İkili aramanın her adımda farkı yarıya indirmesine'], 'Aralık n − 1 eşit kovaya bölünürse güvercin yuvası ilkesiyle en az bir kova boş kalır; en büyük boşluk kova genişliğinden küçük olamaz. Bu yüzden yalnız her kovanın en küçük ve en büyük değeri tutulur.'),
  ('Bilinmeyen bir dilin alfabe sırası verilmiş ve bir sözcük listesinin bu sıraya göre sıralı olup olmadığı denetlenecek. En verimli yol hangisidir?', 'Her harfe alfabedeki sırasını veren bir tablo kurup yalnız komşu sözcükleri karşılaştırmak', ['Bütün sözcükleri İngiliz alfabesine göre yeniden sıralayıp karşılaştırmak', 'Her sözcüğü listedeki bütün sözcüklerle tek tek karşılaştırmak', 'Sözcükleri uzunluklarına göre sıralayıp yalnız listenin ilk ve son sözcüğünü bilinmeyen alfabeye göre karşılaştırmak'], 'Sıralılık için komşu çiftlerin doğru sırada olması yeterlidir. Her komşu çiftte ilk farklı harf, tablodaki sıra numaralarıyla karşılaştırılır.'),
  ('Sıralı 1, 2, 3, 4, 5 dizisinde 3\'e en yakın 4 eleman isteniyor; eşit uzaklıkta küçük olan tercih ediliyor. Sonuç hangisidir?', '1, 2, 3 ve 4', ['2, 3, 4 ve 5', '1, 2, 4 ve 5', '2, 3 ve 4'], 'Uzaklıklar 2, 1, 0, 1, 2\'dir; 3, 2 ve 4 alınır, dördüncü için 1 ile 5 eşit uzaklıktadır ve küçük olan 1 seçilir. Pratikte ikili arama ve iki işaretçiyle O(log n + k) sürede bulunur.'),
  ('Bir sözlük uygulamasında \'-lık\' ile biten bütün sözcükler hızla listelenmek isteniyor. Önek aramasına benzer bir çözüm için ne hazırlanır?', 'Sözcüklerin ters çevrilmiş hâllerinden oluşan sıralı bir liste', ['Sözcüklerin uzunluklarına göre sıralanmış ve her uzunluk için ayrı tutulan listeleri', 'Sözcüklerin rastgele karıştırılmış bir kopyası', 'Yalnız sesli harflerden oluşan bir dizin'], 'Ters çevrilmiş sözcüklerde \'kıl\' ile başlayanlar sıralı listede ardışık bir blok oluşturur; bu blok iki ikili aramayla bulunur ve sözcükler yeniden ters çevrilir.'),
  ('İntihal tespit sistemleri belgelerden \'parmak izi\' çıkarırken metindeki her k uzunluklu parçanın karmasını hesaplar. Bu hesaplamayı her parça için hızlı yapan teknik hangi arama algoritmasından gelir?', 'Rabin–Karp\'ın kayan karması', ['İkili aramanın orta nokta hesabı', 'Kabarcık sıralamasının komşu takası', 'Üstel aramanın ikiye katlama adımı'], 'Kayan karma, pencere bir karakter kaydığında yeni değeri sabit sürede hesaplar. Belgelerin karma kümeleri karşılaştırılarak ortak parçalar bulunur.'),
  ('Her karşılaştırmanın çok pahalı olduğu (ör. iki uzun belgeyi bir uzmanın karşılaştırması) ama öğeleri taşımanın ucuz olduğu bir durumda hangi algoritma tercih edilmelidir?', 'Birleştirmeli sıralama ya da ikili eklemeli sıralama', ['Kabarcık sıralaması', 'Seçmeli sıralama', 'Stooge sıralaması'], 'Bu algoritmalar karşılaştırma sayısını n log n\'e yakın tutar. Kabarcık ve seçmeli sıralama ise yaklaşık n²/2 karşılaştırma yapar; seçmeli sıralama yalnız taşıma pahalı olduğunda avantajlıdır.'),
  ('Bir sınav sonuç listesinde eşit puanlı öğrencilerin sırası her yayımlamada rastgele belirlenmek isteniyor. Basit ve doğru yöntem hangisidir?', 'Listeyi önce rastgele karıştırıp sonra puana göre kararlı sıralamak', ['Puana göre kararsız bir algoritmayla sıralamak', 'Puanlara küçük rastgele sayılar ekleyip sonucu yuvarlamak', 'Listeyi önce ada göre sıralayıp sonra tamamen ters çevirmek ve her yayımlamada bunu tekrarlamak'], 'Kararlı sıralama eşitlerin karıştırmadan gelen rastgele sırasını korur. Kararsız algoritmanın eşitleri dizişi ise rastgele değil, algoritmaya bağlı ve öngörülebilir olabilir.'),
  ('Ağırlıkları 1, 3 ve 6 olan üç seçenekten ağırlıkla orantılı rastgele seçim yapılıyor: birikimli toplamlar [1, 4, 10] hesaplanıyor ve [0, 10) aralığında çekilen r için birikimli değeri r\'den büyük ilk konum ikili aramayla bulunuyor. r = 5 ise hangi seçenek seçilir?', 'Üçüncü seçenek', ['Birinci seçenek', 'İkinci seçenek', 'İkinci ve üçüncü seçenek birlikte'], '4 ≤ 5 < 10 olduğundan r üçüncü seçeneğin [4, 10) dilimine düşer. Birikimli dizi sıralı olduğundan seçim O(log n) sürede yapılır.'),
  ('Yığın sıralamasına yakıştırılan özelliklerden hangisi gerçeği yansıtmaz?', 'Neredeyse sıralı girdide doğrusal sürede biter', ['Yerinde çalışır', 'En kötü durumda da, yani her türlü girdide, n log n mertebesinde sürede biter', 'Kararlı değildir'], 'Yığın kurulumu ve her çıkarmadaki süzme, girdinin önceden sıralı olmasından yararlanmaz; süre her durumda n log n mertebesindedir.'),
  ('Python\'da \'abc\'.count(\'\') ifadesi hangi değeri verir?', '4', ['0', '3', '1'], 'Boş kalıp her karakterin önünde ve metnin sonunda eşleşir; 3 karakterli metinde 4 konum vardır. Bu, arama işlevlerinde boş kalıbın ayrıca ele alınması gerektiğini gösterir.'),
  ('Çakışan aralıklar birleştirilerek başlangıca göre sıralı, birbirinden ayrık aralıklar elde edildi. Bir noktanın bu aralıklardan birinin içinde olup olmadığı nasıl hızlı bulunur?', 'Başlangıcı noktayı aşmayan son aralık ikili aramayla bulunup sonu denetlenir', ['Bütün aralıklar baştan sona taranır', 'Yalnız ilk aralığa bakılır; nokta onun içinde değilse hiçbir aralıkta değildir', 'Aralıklar yeniden birleştirilir ve noktanın aralık sayısına oranı hesaplanır'], 'Ayrık ve sıralı aralıklarda noktayı içerebilecek tek aday, başlangıcı noktadan büyük olmayan son aralıktır. Taban araması O(log n) sürer.'),
  ('Büyük değerler küçük sıra numaralarına dönüştürülmek isteniyor (\'koordinat sıkıştırma\'). 40, 10, 40, 25 değerleri sıralanıp tekrarlar atıldıktan sonra her değer, bu listedeki indisiyle (0\'dan) değiştirilirse sonuç ne olur?', '2, 0, 2, 1', ['3, 0, 2, 1', '1, 0, 1, 2', '4, 1, 4, 2'], 'Tekrarsız sıralı liste 10, 25, 40\'tır; 10 → 0, 25 → 1, 40 → 2. Her değerin sırası ikili aramayla bulunur ve değerlerin göreli düzeni korunur.'),
  ('Python 3.10 ile bisect modülündeki işlevlere eklenen yenilik hangisidir?', 'Sıralama anahtarını belirten key parametresi', ['Azalan sıralı dizilerde çalışmayı sağlayan reverse parametresi', 'Bağlı listelerde ikili arama yapabilme', 'Aramanın kaç adım sürdüğünü döndürme'], 'key parametresiyle örneğin nesne listesinde bir alana göre ikili arama yapılabilir; liste aynı anahtara göre sıralı olmalıdır.'),
  ('Üç girdiyi her durumda sıralayan bir sıralama ağı en az kaç karşılaştırıcı gerektirir?', '3', ['2', '4', '6'], 'Örneğin (1,2), (2,3), (1,2) karşılaştırıcıları üç değeri sıralar. İki karşılaştırıcı yetmez, çünkü 3! = 6 olasılık 2² = 4 sonuçla ayırt edilemez.'),
  ('100, 4, 200, 1, 3, 2 dizisinde ardışık tam sayılardan oluşan en uzun dizinin (ör. 1, 2, 3, …) uzunluğu, dizi sıralandıktan sonra tek taramayla bulunuyor. Sonuç kaçtır?', '4', ['3', '6', '2'], 'Sıralı dizi 1, 2, 3, 4, 100, 200\'dür. Komşu farkı 1 olduğu sürece sayaç artar: 1–2–3–4 dizisi 4 uzunluğundadır.'),
  ('A = [1, 3, 15, 11, 2] ve B = [23, 127, 235, 19, 8] dizilerinden birer eleman seçilerek farkın mutlak değeri en küçük yapılacak. İki dizi sıralanıp iki işaretçiyle taranırsa en küçük fark kaç bulunur?', '3', ['4', '1', '6'], 'Sıralı diziler 1, 2, 3, 11, 15 ve 8, 19, 23, 127, 235\'tir. Her adımda küçük olan taraf ilerletilir; en küçük fark |11 − 8| = 3\'tür.'),
  ('Bir öğrencinin ders programındaki derslerin birbiriyle çakışıp çakışmadığı denetlenecek. En verimli yöntem hangisidir?', 'Dersleri başlangıç saatine göre sıralayıp her dersi yalnız bir öncekiyle karşılaştırmak', ['Her dersi diğer bütün derslerle tek tek karşılaştırmak', 'Dersleri adlarına göre alfabetik sıralayıp yalnız komşu derslerin saatlerine bakmak', 'Yalnız ilk ve son dersin saatlerini karşılaştırmak'], 'Sıralamadan sonra bir çakışma varsa mutlaka ardışık iki ders arasında görülür: bir dersin başlangıcı öncekinin bitişinden önceyse çakışma vardır. Süre n log n olur.'),
  ('Python\'da sorted([3, None, 1], key=lambda v: (v is None, v)) ifadesi None değerini nereye yerleştirir?', 'Listenin sonuna', ['Listenin başına', 'Ortaya, 1 ile 3 arasına', 'Hiçbir yere; TypeError verir'], 'Anahtarın ilk öğesi None için True (1), sayılar için False (0) olur; sayılar önce gelir. None\'lar kendi aralarında yalnız ilk öğeyle ayrıldığından karşılaştırma hatası oluşmaz. Sonuç [1, 3, None]\'dır.'),
  ('Değerleri düzgün dağılmış 65 536 (2¹⁶) elemanlı sıralı bir dizide interpolasyon aramasının ortalama deneme sayısı log₂(log₂ n) ile tahmin edilirse yaklaşık kaç deneme beklenir?', '4', ['16', '8', '256'], 'log₂ 65 536 = 16 ve log₂ 16 = 4\'tür. Aynı dizide ikili arama yaklaşık 16 karşılaştırma yapar.'),
  ('Python\'da sorted([3, 8, 7, 5], key=lambda x: bin(x).count(\'1\')) ifadesi sayıları ikilik gösterimdeki 1 bitlerinin sayısına göre sıralar. Sonuç nedir?', '[8, 3, 5, 7]', ['[3, 5, 7, 8]', '[7, 5, 3, 8]', '[8, 7, 5, 3]'], '1 bit sayıları 3 → 2, 8 → 1, 7 → 3, 5 → 2\'dir. Anahtara göre 8 önce gelir; 3 ile 5 eşittir ve kararlılık gereği özgün sıralarını korur; en sonda 7 gelir.'),
  ('Posta kodları (ör. \'01234\') bir kayıt sisteminde sayı olarak saklanınca bazı sorunlar çıkıyor. Kodları beş karakterlik metin olarak saklamanın sıralama ve arama açısından yararı nedir?', 'Baştaki sıfırlar korunur ve sabit uzunluk sayesinde metin sırası sayısal sırayla aynı olur', ['Metinler sayılardan daha hızlı karşılaştırılır', 'Metin olarak saklanan kodlar hiçbir biçimde sıralanamaz; bu da yanlış sıralama hatasını tamamen önler', 'Kodlar otomatik olarak şehir adına göre sıralanır'], 'Sayı olarak saklanınca \'01234\' 1234\'e dönüşür ve aramada bulunamaz. Bütün kodlar aynı uzunlukta metin olunca sözlük sırası doğru sonucu verir.'),
];
